const PACKAGE={"id":"BFSdual_LF06_Lernpfad_LS6_3","ls":"6.3","title":"Lernpfadübung · LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","version":"1.1","source":"Fachbereiche/BFSdual/LF06/LS_6_3_Fachgeschaeft_gestalten.md"};
const COMP=[["Fachkompetenz","Ich plane eine kleine Beratungsfläche. Ich begründe, welche Artikel ich zusammen zeige. Ich erkläre, wie man die Artikel gut erreicht und am Fahrrad zeigen kann."],["Personalkompetenz","Ich ändere meinen Entwurf, wenn er bei der Beratung zu Problemen führt."],["Sozialkompetenz","Ich bespreche mit anderen, welche Wege die Kundschaft und das Verkaufspersonal brauchen."],["Methodenkompetenz","Ich übertrage Maße in eine Skizze oder ein Modell. Damit vergleiche ich zwei Anordnungen."],["Medienkompetenz","Ich beschrifte den Plan und erkläre die Zeichen in einer Legende. So können andere ihn lesen."]];
const BANK=[{"title":"Wenn zwei Fahrräder zusammentreffen","scene":"Bei Block möchte eine Kundin sehen, wie die Halterung eines Lichts am Lenker sitzt. Gleichzeitig kommt ein zweiter Kunde mit seinem Rad durch denselben Bereich.","ask":"Welche Aussagen beschreiben die Situation?","options":["Die Verkäuferin bringt ein Musterlicht.","Der zweite Kunde kommt ohne Fahrrad.","Beide Personen halten mit ihren Rädern an.","Die Kundin testet die Minipumpe ohne Hilfe.","Die Vorführung und der Weg des zweiten Kunden beanspruchen denselben Bereich.","Die Ladenleitung hat den Aufbau bereits getestet."],"answer":[0,2,4],"why":"Das Musterlicht soll am Rad gezeigt werden. Als ein zweites Rad durch denselben Bereich kommt, halten beide an. Der Aufbau wird erst am nächsten Vormittag getestet.","hint":"Schau auf den Augenblick, in dem die Verkäuferin zurückkommt.","steps":"Trenne, wer welches Rad bewegt und was die Verkäuferin mitbringt.","example":"Ein Beispiel für zwei gleichzeitige Handlungen ist Greifen ins Regal und Vorbeischieben am Regal.","c":2,"sourceRefs":["Handlungssituation"],"id":0,"l":1,"type":"multi","caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Zwei Sichtweisen auf dieselbe Fläche","scene":"Sebastian Wolf und Christian Klein arbeiten bei Global Bike. Beide achten bei der Aktion auf verschiedene Teile eines praktikablen Aufbaus.","ask":"Was wollen die beiden im Fall erreichen?","options":["Christian möchte die Werkstatt an einen anderen Platz verlegen.","Sebastian möchte, dass mehr Platz für die Vorführung am Rad da ist.","Christian achtet auf den Zugriff auf die verpackte Ware.","Sebastian möchte das Zubehör nur auf Schildern erklären.","Christian will zwei andere Zubehörartikel bestellen.","Sebastian möchte den Beratungstresen als Vorführplatz nutzen."],"answer":[1,2],"why":"Sebastian achtet auf Platz am Rad. Christian achtet darauf, dass das Personal die verpackte Ware auch während der Beratung erreicht.","hint":"Lies nach, worauf jede Person im Fall direkt hinweist.","steps":"Ordne die Aussagen zu Vorführung oder Warenzugriff.","example":"Eine Beratung kann am Vorführrad beginnen und mit dem Griff zur Verpackung enden.","c":2,"sourceRefs":["Handlungssituation","M2"],"id":1,"l":1,"type":"multi","caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Was für den Aufbau bereitsteht","scene":"Die Ladenleitung will den Aufbau am nächsten Vormittag ausprobieren. Regale und Tisch stehen für den Versuch bereit.","ask":"Welche Dinge sind bewegliche Warenträger der Aktion?","options":["Das Vorführrad.","Der feste Beratungstresen.","Das erste Rollregal.","Der eingezeichnete Platz zum Vorführen.","Das zweite Rollregal.","Der schmale Tisch."],"answer":[2,4,5],"why":"Block nutzt zwei bewegliche Rollregale und einen schmalen Tisch als Warenträger. Das Vorführrad dient als Modell, der Tresen bleibt fest und der Vorführplatz braucht freien Boden.","hint":"Warenträger sind die Möbel für die Aktionsware.","steps":"Unterscheide bewegliche Möbel, feste Möbel und freie Flächen.","example":"Auf einen Warenträger kannst du verpackte Ware stellen.","c":0,"sourceRefs":["Handlungssituation","M2","M6"],"id":2,"l":1,"type":"multi","caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Zugriffsseiten lesbar markieren","scene":"Die lange Bedienseite des Rollregals ist im Plan mit einem Pfeil markiert. Ein zweiter Pfeil soll den Weg zur Werkstatt zeigen.","ask":"Welche Darstellungen helfen, die beiden Bedeutungen auseinanderzuhalten?","options":["Den Zugriffspfeil direkt an die lange Seite des Rollregals setzen.","Die Bedeutung beider Pfeile unter „Aktion“ zusammenfassen.","Die Bedienseite am Nordpfeil des Grundrisses ablesen lassen.","Für den Werkstattweg und die Bedienseite unterschiedliche Zeichen in der Legende erklären.","Den ganzen Gang als Möbel markieren.","Den Pfeil zum Regal auf das nächste Produktfoto setzen."],"answer":[0,3],"why":"Der Ort des Zeichens zeigt, welche Regalseite gemeint ist. Die Legende unterscheidet den Zugriff am Regal vom Weg zur Werkstatt.","hint":"Welches Zeichen zeigt einen Ort, welches eine Richtung durch den Laden?","steps":"Prüfe Zeichen, Lage im Plan und Legende getrennt.","example":"Ein kurzer Pfeil direkt aufs Regal kann die Bedienseite zeigen. Eine Linie entlang des Gangs kann für einen Weg stehen.","c":4,"sourceRefs":["M1","M2","M4"],"id":3,"l":1,"type":"multi","caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Zwei Muster, zwei Zwecke","scene":"Block stellt ein Vorführrad bereit. Für einige Produkte gibt es außerdem ein Muster.","ask":"Welche Zuordnungen stimmen?","options":["Der Flächenplan ist das Vorführmodell für das Zubehör.","Das Vorführrad dient als Modell für die Demonstration.","Ein Muster ist die für die Aktion reservierte Stelle im Gang.","Ein Muster des Lichtsets kann beim Ansetzen der Halterung benutzt werden.","Die Luft im Reifen ist das Muster für die Minipumpe.","Ein leeres Taschenmuster kann man anfassen und öffnen."],"answer":[1,3,5],"why":"Das Rad ist das Modell, an dem etwas gezeigt wird. Licht und Tasche sind Muster der eigentlichen Produkte. Die Kundschaft kann die Funktion oder Handhabung daran ausprobieren.","hint":"Unterscheide den Artikel, den du zeigst, und den Gegenstand, an dem du ihn zeigst.","steps":"Ordne je ein Beispiel dem Vorführmodell, dem Muster oder dem Plan zu.","example":"Ein Lenker ist Teil des Vorführmodells. Die daran angesetzte Halterung ist Zubehör.","c":0,"sourceRefs":["M2","M3","M6"],"id":4,"l":1,"type":"multi","caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Zonen im Grundriss einordnen","scene":"M1 zeigt den Hauptdurchgang links von x = 0,00 bis x = 1,20 m. Die Aktionsfläche beginnt bei x = 1,20 m und liegt oberhalb von y = 0,80 m. Der feste Tresen liegt bei x = 3,60–4,80 m und y = 0,80–1,50 m.","ask":"Welche Angaben helfen, die Flächen für zwei Entwürfe gleich einzuzeichnen?","options":["Die linke Gangfläche in voller Breite bis zur Werkstatt markieren.","Die Aktionsfläche schon bei x = 0,00 m beginnen lassen.","Die Grenze bei x = 1,20 m in beiden Skizzen an derselben Stelle setzen.","Den Tresen bei jedem neuen Entwurf an eine beliebige Stelle zeichnen.","Den festen Tresen in beiden Plänen an seinen angegebenen Koordinaten belassen.","Den Hauptdurchgang nur als Punkt am Werkstatteingang einzeichnen."],"answer":[0,2,4],"why":"Hauptdurchgang, Aktionsflächengrenze und Tresen ändern sich zwischen den Entwürfen nicht. Mit denselben Referenzflächen lassen sich die Anordnungen vergleichen.","hint":"Unterscheide feste Flächen und bewegliche Warenträger.","steps":"Übertrage die x- und y-Werte zuerst in beide Skizzen. Vergleichsgrößen sollen sich beim Entwerfen nicht verschieben.","example":"Hat ein Punkt den festen x-Wert 1,20 m, liegt er von der linken Plankante aus immer gleich weit rechts.","c":3,"sourceRefs":["M1","M2"],"id":5,"l":1,"type":"multi","caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Ersten Warenplatz für ein schweres Schloss hinterfragen","scene":"Übungsvariante: Du hast das Bügelschloss S20 zuerst oben im Regal eingezeichnet, damit man es gut sieht. In M3 liest du, dass es wegen seines Gewichts unten stehen soll.","ask":"Wie gehst du mit deinem eigenen Vorschlag um?","options":["Beim bisherigen Vorschlag bleiben, weil er schon eingezeichnet ist.","Das Schloss in die untere Regalzone einplanen.","Die neue Platzierung mit der Vorgabe zum Gewicht begründen und den Zugriff prüfen.","Nur den Produktcode am oberen Platz ändern.","Das Schloss aus dem festgelegten Sortiment streichen.","Die Beratung zum Schloss auf den Hauptdurchgang verlegen."],"answer":[1,2],"why":"Der erste Entwurf darf sich ändern, sobald eine Anforderung dagegen spricht. Das Gewicht bestimmt beim Schloss die Regalzone. Der Platz unten muss erreichbar bleiben.","hint":"Vergleiche die zuerst gewählte Höhe mit der Artikelvorgabe.","steps":"Entscheide, was sich ändern muss, und begründe den Eingriff aus M3.","example":"Eine Änderung des Entwurfs lässt sich mit einer konkreten Eigenschaft des Artikels begründen.","c":1,"sourceRefs":["M2","M3","M5"],"id":6,"l":1,"type":"multi","caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Musterlicht und Lichtschachteln","scene":"Die Kundin möchte die Halterung sehen und sich zeigen lassen, wie sie das Licht wieder löst.","ask":"Was muss die Anordnung für L10 leisten?","options":["Ein Musterlicht ist am Vorführplatz verfügbar.","Alle Lichtschachteln gehören auf den Boden neben dem Rad.","Die Verkäuferin kommt auch während der Beratung an die verpackten Lichtsets.","Das Lichtset wird neben dem Eingang im Hauptdurchgang aufbewahrt.","Um Ware zu greifen, muss die Vorführung grundsätzlich beendet werden.","Die Halterung lässt sich am Lenker zeigen."],"answer":[0,2,5],"why":"Muster am Vorführplatz und erreichbare Schachteln erfüllen unterschiedliche Zwecke. Die Halterung kann am Lenker angesetzt und wieder gelöst werden.","hint":"Suche in M3 nach zwei getrennten Angaben zu L10.","steps":"Prüfe erst, was die Kundin ausprobieren will, dann, was das Personal verkaufen können soll.","example":"Das abgesteckte freie Rechteck zum Vorführen braucht keine Schachteln auf dem Boden.","c":0,"sourceRefs":["M3"],"id":7,"l":1,"type":"multi","caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Welche Frage gehört zu welchem Artikel?","scene":"Die Kundschaft fragt zu den Aktionsartikeln nach Handhabung und Eignung.","ask":"Welche Zuordnungen stimmen?","options":["T30 Rahmentasche: Komme ich gut an meine Kleinteile?","P50 Minipumpe: Wie löse ich das Licht von der Halterung?","R40 Sattelüberzug: Kann ich ihn am Sattel ausprobieren?","S20 Bügelschloss: Passt der Pumpenkopf zum Ventil?","P50 Minipumpe: Wie setze ich sie am Ventil an?","L10 LED-Lichtset: Wie groß ist der Bügel?"],"answer":[0,2,4],"why":"Zugriff auf Kleinteile gehört zur Rahmentasche, der Sitz am Sattel zum Sattelüberzug und das Ansetzen am Ventil zur Minipumpe.","hint":"Vergleiche die Stelle am Rad oder die Nutzung je Artikel.","steps":"Unterstreiche in jeder Frage das Wort, das die Nutzung verrät.","example":"Greifen, befestigen und aufpumpen beschreiben unterschiedliche Tätigkeiten.","c":0,"sourceRefs":["M3"],"id":8,"l":1,"type":"multi","caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Maßstab im Flächenplan","scene":"Im Plan wird der Verkaufsbereich im Maßstab 1:20 gezeichnet. Der wirkliche Bereich misst 4,80 m × 4,00 m.","ask":"Welche Aussagen sind richtig?","options":["4,80 m werden im Plan zu 12 cm.","Bei 1:20 entspricht 1 cm im Plan 20 cm im Laden.","4,00 m werden im Plan zu 20 cm.","Die 4,80 m sind im Plan 24 cm breit.","Die Werte aus dem Laden werden für den Plan verdoppelt.","1 cm im Plan entspricht 2 m im Laden."],"answer":[1,2,3],"why":"Für den Plan rechnest du die Wirklichkeit zuerst in Zentimeter um und teilst dann durch 20. 480 cm ergeben 24 cm, 400 cm ergeben 20 cm.","hint":"Schreib beide wirklichen Maße zunächst in Zentimetern.","steps":"Teile jedes Zentimetermaß durch 20 und kontrolliere die Zuordnung von Breite und Tiefe.","example":"Bei 1:20 werden aus 200 cm im Laden 10 cm auf dem Papier.","c":3,"sourceRefs":["M1"],"id":9,"l":1,"type":"multi","caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Was andere im Plan erkennen sollen","scene":"Das Team reicht einen Flächenplan ein. Ein anderes Team soll ihn prüfen, ohne euch vorher fragen zu müssen.","ask":"Welche Angaben helfen dabei?","options":["Maße von Flächen und Wegen.","Eine Legende, die die Zeichen erklärt.","Ein Produktfoto allein ohne Standort im Plan.","Beschriftete Artikel und markierte Bedienseiten.","Ein Preisrabatt statt der Platzierung von L10.","Eine unbeschriftete Linie für alle Wege und Grenzen."],"answer":[0,1,3],"why":"Maße, verständliche Zeichen und benannte Warenplätze oder Bedienseiten machen den Plan ohne mündliche Ergänzung prüfbar.","hint":"Stell dir vor, du liest den Plan zum ersten Mal.","steps":"Prüfe, ob andere anhand der Angabe messen, etwas finden oder ein Zeichen verstehen können.","example":"Eine gestrichelte Linie kann einen freien Weg markieren, wenn die Legende das erklärt.","c":4,"sourceRefs":["M1","M4","M5"],"id":10,"l":1,"type":"multi","caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Wann ein guter Entwurf geändert wird","scene":"Im ersten Test stehen die Waren wie vorgesehen. Beim Vorführen steht ein Vorderrad vor der Bedienseite.","ask":"Welche Reaktionen passen zur Aufgabe?","options":["Die Probe als erfolgreich eintragen, weil die Möbel in die Aktionsfläche passen.","Die blockierte Stelle im Plan markieren.","Nur die Farbe für den Hauptdurchgang ändern.","Den Aufbau so anpassen, dass die Bedienseite beim Vorführen nutzbar bleibt.","Die Vorführung erneut mit einem zweiten Rad prüfen.","Das Schloss höher stellen, obwohl der Zugriff am Lichtregal blockiert ist."],"answer":[1,3,4],"why":"Markiere das beobachtete Problem, passe die Anordnung an und wiederhole die Beratungsszene. So zeigt die zweite Probe, ob die Änderung den Zugriff verbessert.","hint":"Schau auf die Ursache der Blockade und auf den Nachweis einer Verbesserung.","steps":"Ordne die sinnvollen Schritte als beobachten, ändern, erneut prüfen.","example":"Eine geänderte Farbe hilft beim Lesen. Ein Vorderrad vor dem Regal braucht eine Änderung der Anordnung.","c":1,"sourceRefs":["M2","M4","M5"],"id":11,"l":1,"type":"multi","caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Ein Rechteck für die Vorführung","scene":"Übungsvariante: Drei freie Rechtecke sind 2,10 m × 1,25 m, 1,30 m × 2,00 m und 1,95 m × 1,40 m groß. Die Regel fordert mindestens 2,00 m × 1,30 m. Keine andere Fläche wird dabei belegt.","ask":"Welche Prüfaussagen stimmen?","options":["2,10 m × 1,25 m reicht aus, weil das Rechteck länger als 2,00 m ist.","1,30 m × 2,00 m reicht aus, wenn die Orientierung im Grundriss passt.","1,95 m × 1,40 m reicht aus, weil die Fläche insgesamt größer ist.","2,10 m × 1,25 m ist um 0,05 m zu schmal.","1,95 m × 1,40 m ist an der langen Seite um 0,05 m zu kurz.","Ein hochkant gezeichnetes Rechteck ist grundsätzlich unzulässig."],"answer":[1,3,4],"why":"Beide Seiten müssen ihr Mindestmaß erreichen. Die lange Seite darf in x- oder y-Richtung liegen. Mehr Platz auf einer Seite gleicht ein fehlendes Maß auf der anderen Seite nicht aus.","hint":"Ordne jedem Rechteck seine längere und kürzere Seite zu.","steps":"Vergleiche jede lange Seite mit 2,00 m und jede kurze mit 1,30 m.","example":"Ein freier Bereich kann groß wirken, obwohl ein Maß für das Fahrrad fehlt.","c":3,"sourceRefs":["M2"],"id":12,"l":2,"type":"multi","caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Wie breit ist der Weg in Wirklichkeit?","scene":"Übungsvariante: In zwei Plänen im Maßstab 1:20 sind die engsten Stellen zum Vorführplatz 4,2 cm und 4,5 cm breit. Der erforderliche Weg ist überall mindestens 0,90 m breit.","ask":"Welche Aussagen stimmen?","options":["4,2 cm entsprechen 0,84 m.","4,5 cm entsprechen 0,45 m.","Die schmalere Stelle verfehlt die Vorgabe um 0,06 m.","4,5 cm entsprechen genau dem Mindestmaß.","Beide Wege genügen, solange die breite Stelle 4,5 cm erreicht.","4,2 cm entsprechen 1,20 m."],"answer":[0,2,3],"why":"Multipliziere das Planmaß mit 20. 84 cm fehlen 6 cm zu 90 cm. 4,5 cm entsprechen 90 cm. Die Regel gilt an der engsten Stelle und auf dem restlichen Weg.","hint":"Rechne zuerst von Plan-Zentimetern in wirkliche Zentimeter um.","steps":"Vergleiche die Ergebnisse mit 90 cm. Achte auf die engste Stelle.","example":"3 cm auf dem Blatt entsprechen bei diesem Maßstab 60 cm im Laden.","c":3,"sourceRefs":["M2","M4"],"id":13,"l":2,"type":"multi","caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Papiermodelle für den Test","scene":"Du baust die Anordnung im Maßstab 1:20. Das Rollregal misst 1,00 m × 0,40 m, der Tisch 0,80 m × 0,55 m. Für das Rad sind 1,80 m × 0,65 m angesetzt.","ask":"Welche Zuschnitte sind richtig?","options":["Rollregal: 10,0 cm × 4,0 cm.","Tisch: 4,0 cm × 2,75 cm.","Fahrrad: 9,0 cm × 3,25 cm.","Rollregal: 5,0 cm × 2,0 cm.","Tisch: 4,0 cm × 4,5 cm.","Fahrrad: 18,0 cm × 6,5 cm."],"answer":[1,2,3],"why":"Teile die wirklichen Zentimeter jeweils durch 20. So ergeben sich 5,0 × 2,0 cm, 4,0 × 2,75 cm und 9,0 × 3,25 cm.","hint":"Verwende dieselbe Rechnung für jede einzelne Seite.","steps":"Schreibe alle wirklichen Längen in Zentimetern auf und teile sie jeweils durch 20.","example":"Für 60 cm wirkliche Länge wären im Modell 3 cm nötig.","c":3,"sourceRefs":["M2","M4"],"id":14,"l":2,"type":"multi","caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Eine eigene Platzierung korrigieren","scene":"Übungsvariante: Dein Regal reicht im Plan von x = 1,00 bis x = 2,00 m und von y = 2,00 bis y = 2,40 m. Hauptdurchgang und Aktionsfläche treffen bei x = 1,20 m aufeinander. Ein Teammitglied weist auf eine Überschneidung hin.","ask":"Welche Reaktion verbessert deinen Entwurf?","options":["Das Regal unverändert lassen und nur die Bedienseite drehen.","Den Plan korrigieren, weil das Regal 0,20 m in den Hauptdurchgang ragt.","Den Standort beibehalten, weil mehr als die Hälfte des Regals auf der Aktionsfläche liegt.","Nach dem Versetzen den freien Weg zur Bedienseite erneut prüfen.","Die Grenze der Aktionsfläche verschieben, damit das Regal vollständig hineinpasst.","Den Einwand zurückweisen, weil der Hauptdurchgang im Entwurf anders eingefärbt ist."],"answer":[1,3],"why":"Von x = 1,00 bis 1,20 m stehen 20 cm des Regals im Gang. Die Korrektur muss die Überschneidung entfernen und den Zugriff am neuen Standort sichern.","hint":"Überprüfe die Rückmeldung am eigenen Plan.","steps":"Vergleiche die x-Werte und kontrolliere nach einer Korrektur auch die neue Bedienseite.","example":"Ein Regal kann größtenteils in der richtigen Fläche liegen und trotzdem eine feste Grenze überschreiten.","c":1,"sourceRefs":["M1","M2"],"id":15,"l":2,"type":"multi","caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Welcher Entwurf eignet sich für den Probelauf?","scene":"Übungsvariante: Entwurf A hat einen freien Vorführplatz von 2,10 m × 1,30 m. Beim Vorführen misst der schmalste Weg zur Bedienseite 0,85 m. In Entwurf B misst der Vorführplatz 2,00 m × 1,35 m, der dortige Weg überall mindestens 0,95 m. Hauptdurchgang und Tresenzugang bleiben in beiden Entwürfen frei.","ask":"Welche Folgerungen treffen zu?","options":["A erfüllt die Wegregel, weil die 0,85 m nur während der Vorführung gemessen wurden.","Beide Vorführplätze erfüllen das Mindestmaß.","B ist nach den vorliegenden Maßen besser geeignet.","A bietet am schmalsten Punkt 0,05 m Reserve zur Wegvorgabe.","B muss nichts an der Erreichbarkeit der verpackten Ware überprüfen.","In A verfehlt der Weg zur Bedienseite das Mindestmaß."],"answer":[1,2,5],"why":"Beide Vorführplätze sind groß genug. Bei A fehlen beim Greifen 0,05 m Wegbreite. B erfüllt die genannten Maße. Die tatsächlichen Handgriffe prüfst du anschließend im Probelauf.","hint":"Trenne Vorführplatz, Wegbreite und praktische Greifprobe.","steps":"Bewerte beide Entwürfe jeweils mit denselben Maßen und halte offene Fragen fest.","example":"Ein Maß kann erfüllt sein und dennoch einen Praxistest erforderlich machen.","c":2,"sourceRefs":["M2","M5"],"id":16,"l":2,"type":"multi","caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Artikel so gruppieren, dass die Beratung gelingt","scene":"Übungsvariante: Dein Team zeichnet die Warenplätze und will die Zusammenstellung kurz erklären.","ask":"Welche Begründungen tragen fachlich?","options":["Musterlicht und verpackte Lichtsets bekommen unterschiedliche, einander zugeordnete Plätze.","Die Minipumpe soll beim Vorführen am Ventil griffbereit sein.","Das Schloss steht wegen seiner Masse am höchsten, damit es sich aus der Beratungszone greifen lässt.","Sattelüberzug und Rahmentasche müssen an einer einzigen Stelle sichtbar sein, weil beide aus Textil bestehen.","Beim Taschenmuster ist Platz zum Anfassen und Öffnen ein sinnvolles Kriterium.","Die verpackte Ware kann beim Versuch überall stehen, wenn die freien Wege eingezeichnet sind."],"answer":[0,1,4],"why":"Die Platzierung folgt der tatsächlichen Kundenfrage. Licht braucht Muster und erreichbare Schachteln, die Pumpe Nähe zur Ventilvorführung und die Tasche ein zugängliches leeres Muster.","hint":"Lies die Kundenaussage und die Vorgabe je Artikel gemeinsam.","steps":"Prüfe, was während der Beratung gegriffen, befestigt oder geöffnet wird.","example":"Eine gut sichtbare Ware ist noch nicht automatisch gut vorführbar.","c":0,"sourceRefs":["M2","M3"],"id":17,"l":2,"type":"multi","caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Welche Wege fehlen im Rollenspiel?","scene":"Im Test zeigt das Team die Lichtmontage am Kundinnenrad. Die zweite Rolle muss mit einem Rad zur Werkstatt. Eine dritte Person verkauft am Tresen weiter.","ask":"Welche Beobachtungen helfen, den Ablauf zu verbessern?","options":["Ob das Kundinnenrad am Eingang einen guten ersten Eindruck macht.","Ob die beratende Person beim Vorführen zur verpackten Ware kommt.","Ob das zweite Rad den Hauptdurchgang nutzen kann, ohne dass der Versuch unterbrochen wird.","Ob der Weg zum Tresen im Ablauf frei bleibt.","Ob die beratende Person die Form des Bügelschlosses genauer erklären kann als andere.","Ob sich das Vorführrad auch außerhalb der Ladenöffnungszeit reinigen lässt."],"answer":[1,2,3],"why":"Die Probe soll Greifen, Vorbeischieben und Tresenzugang gleichzeitig abdecken. Eine beobachtete Blockade zeigt, wo der Plan nachgeschärft werden muss.","hint":"Achte auf die drei Personen und ihre jeweiligen Wege.","steps":"Führe die Tätigkeiten zeitgleich aus. Markiere Stellen, an denen jemand anhält oder ausweicht.","example":"Ein freier Gang in einer Probe ohne zweites Fahrrad reicht als Nachweis für Begegnungen kaum aus.","c":2,"sourceRefs":["M2","M4","M5"],"id":18,"l":2,"type":"multi","caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Minipumpe am richtigen Ort erklären","scene":"Das Vorführrad hat ein Sclaverandventil. Eine Person fragt nach der Minipumpe P50 und möchte sehen, wie die Verkäuferin sie ansetzt.","ask":"Welche Schritte passen zur Beratung bei Block?","options":["Die Pumpe wird am Ventil des Vorführrads angesetzt.","Die Verkäuferin zeigt nur, wo die Pumpenverpackung liegt.","Beim Zeigen bleiben der Hauptdurchgang und der Weg zur Ware frei.","Eine erfolgreiche Vorführung an diesem Rad bestätigt automatisch die Eignung für jedes Ventil.","Das Personal muss P50 vor oder während der Beratung am Warenplatz erreichen können.","Die Vorführung findet am Tresen statt, weil der im Plan fest eingezeichnet ist."],"answer":[0,2,4],"why":"Das Rad ermöglicht eine konkrete Demonstration am Sclaverandventil. Ein anderer Ventiltyp braucht eine eigene Eignungsprüfung. Der Plan muss die Erreichbarkeit von P50 und der Wege sichern.","hint":"Prüfe, welches Ventil in M2 genannt wird und was die Kundenfrage in M3 verlangt.","steps":"Überlege getrennt, wo die Pumpe gegriffen und wo sie angesetzt wird.","example":"Ein Muster an einem Rad zeigt zuerst nur, was an genau diesem Rad möglich ist.","c":0,"sourceRefs":["M2","M3","M5"],"id":19,"l":2,"type":"multi","caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Rückmeldung zu einem schwer lesbaren Plan","scene":"Übungsvariante: Auf der Skizze fehlen die Bedeutung der Pfeile, die Artikelkennzeichen und die Maße an einer Engstelle.","ask":"Welche Ergänzungen erleichtern die Prüfung?","options":["Alle Pfeile mit dem Wort „Aktion“ beschriften.","Bedienseiten und Wege mit unterscheidbaren Zeichen und einer Legende darstellen.","Die Engstelle mit Maß und Bezug zum richtigen Weg kennzeichnen.","Die fehlenden Artikelkennzeichen als M1 bis M6 eintragen.","L10, P50 und die anderen Artikel an ihren Warenplätzen kennzeichnen.","Auf dem Plan nur die Maße der Gesamtfläche ergänzen."],"answer":[1,2,4],"why":"Eine klare Legende unterscheidet Bedienseiten und Wege. Eingetragene Maße zeigen den Engpass, Produktcodes kennzeichnen die Warenplätze. M1–M6 sind Materialverweise, keine Produkte.","hint":"Leite aus jeder fehlenden Angabe eine konkrete Ergänzung ab.","steps":"Prüfe nacheinander: Zeichen verstehen, Engstelle messen, Produkt finden.","example":"Ein Maß direkt an der betreffenden Stelle ist leichter zu prüfen als eine unverbundene Zahl neben dem Titel.","c":4,"sourceRefs":["M1","M3","M4","M5"],"id":20,"l":2,"type":"multi","caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Ein Einwand führt zur Nachbesserung","scene":"Übungsvariante: Ein Prüfergebnis lautet: „Die Kundin kann vorbeikommen, aber das Vorderrad steht dabei vor dem Regal. Eure Verkäuferin kommt nicht an L10.“","ask":"Welche Reaktionen verbessern den Entwurf nachvollziehbar?","options":["Die für die Blockade verantwortliche Position im Plan festhalten.","Die Rückmeldung als Geschmacksfrage behandeln und ignorieren.","Die Position des Vorführplatzes oder des Regals so überprüfen, dass Bedienseite und Wege nutzbar sind.","Den Pfeil zum Lichtregal entfernen, weil der Zugriff im Test nicht geklappt hat.","Erneut eine Beratung mit Zugriff auf L10 nachspielen und das Ergebnis notieren.","Die im Test blockierte Bedienseite in beiden Entwürfen vergleichen."],"answer":[0,2,4,5],"why":"Greifproblem und verursachende Position gehören in den Plan. Der Vergleich zeigt mögliche Änderungen. Eine erneute Probe mit der beratenden Rolle prüft, ob die Schachteln erreichbar bleiben.","hint":"Beziehe Rückmeldung, Änderung und erneute Probe auf denselben Arbeitsschritt.","steps":"Stell den Ablauf nach: Wann und wo soll die Verkäuferin an L10 kommen?","example":"Eine Äußerung wie „Regal verschoben“ gewinnt durch eine anschließende Beobachtung an Aussagekraft.","c":1,"sourceRefs":["M2","M4","M5"],"id":21,"l":2,"type":"multi","caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Ein Flächenvergleich mit derselben Messlatte","scene":"Übungsvariante: Zwei Teams vergleichen alternative Beratungsflächen. Das erste zeigt nur ein erfolgreiches Gespräch zum Licht, das zweite nur ein knappes Maß am Tresen.","ask":"Wie wird der Vergleich fair und aussagekräftig?","options":["Beim ersten Entwurf ausschließlich den Vorführplatz bewerten.","In beiden Entwürfen dieselben Wege und Mindestmaße prüfen.","In beiden Entwürfen Licht- und Pumpenberatung erproben.","Jeden Entwurf nach dem bewerten, was das jeweilige Team bereits gut gezeigt hat.","Bei beiden Varianten notieren, ob das Personal die Ware im Versuch erreicht.","Nur das optisch aufgeräumtere Modell als Grundlage nehmen."],"answer":[1,2,4],"why":"Die gleichen Maße, Testszenen und Beobachtungspunkte machen die Entwürfe vergleichbar. Sonst kann ein Vorteil nur daran liegen, dass jeweils andere Dinge geprüft wurden.","hint":"Achte darauf, dass beide Entwürfe dieselben Anforderungen erfüllen müssen.","steps":"Lege gemeinsame Messpunkte und Tests fest, bevor du eine Variante empfiehlst.","example":"Eine Probe mit Licht testet einen anderen Griffweg als eine Probe mit der Minipumpe.","c":3,"sourceRefs":["M2","M5"],"id":22,"l":2,"type":"multi","caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Den Kurzpitch mit Belegen füllen","scene":"Übungsvariante: Im Pitch bleiben zwei Minuten. Die Ladenleitung möchte verstehen, warum ihr eure Anordnung empfehlt.","ask":"Welche Inhalte erfüllen das Ziel?","options":["Den Standort des Vorführplatzes im Plan zeigen.","Für die Empfehlung nur sagen: „Unser Plan ist übersichtlicher.“","Eine Messung oder eine konkrete Beobachtung aus der Probe nennen.","Die Preise aller fünf Artikel auflisten.","Ein Zwischenergebnis zeigen und sagen, wie es zur Entscheidung beigetragen hat.","Alle grundlegenden Begriffe ohne Bezug zum Plan aufsagen."],"answer":[0,2,4],"why":"Zeige die gewählte Anordnung, stütze sie mit einem konkreten Beleg und erkläre, wie das Zwischenergebnis beim Entscheiden geholfen hat.","hint":"Orientiere dich an den drei Schritten im Pitchauftrag.","steps":"Kläre vorab: Was zeigen wir? Was belegt unsere Wahl? Was hat uns beim Entscheiden geholfen?","example":"„Auf dem Papier sind hier 4,5 cm frei“ ist ein prüfbarer Beleg.","c":4,"sourceRefs":["M5"],"id":23,"l":2,"type":"multi","caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Mit einem Rollregal neu planen","scene":"Übungsvariante: Am Morgen der Aufbauprobe fällt ein Rollregal aus. Ein Rollregal und der schmale Tisch bleiben. Das Aktionssortiment und die Vorgaben zu Wegen, Tresen und Vorführplatz gelten weiter.","ask":"Wie verschaffst du dir eine Grundlage für den neuen Aufbau?","options":["Ich zeichne die nutzbaren Flächen neu ein und markiere, welche Maße der bisherige Entwurf weiterhin einhält.","Ich gehe mit der Verkäuferin den Ablauf für Licht und Minipumpe durch und notiere, was sie wann greifen muss.","Ich halte fest, welche Möbel jetzt verfügbar sind, und markiere die Flächen, die beim Umbau geschützt bleiben.","Ich lege die zwei Möbel im Modell und messe nach, welche Bereiche unverändert für Kunden und Personal frei bleiben.","Ich beziehe Werkstatt und Verkauf ein und sammle, an welchen Stellen ihre Wege im Umbau abgesichert sein müssen.","Ich liste zuerst die unveränderlichen Anforderungen auf und lege fest, welche Aufbauschritte bei einem Regal neu geprüft werden."],"consequences":["Deine Skizze gibt dir Vergleichsmaße für den alten und den neuen Aufbau.","Du weißt, welche Warenplätze aus Sicht der Beratung funktionieren müssen.","Du beginnst mit geklärten Ressourcen und geschützten Flächen.","Im Modell siehst du, wo sich durch das fehlende Regal Wege ändern.","Die Anforderungen beider Arbeitsbereiche fließen früh in die Planung ein.","Du hast eine Reihenfolge für die Prüfung und kannst Pflichtbedingungen im Blick behalten."],"why":"Ein fehlendes Regal ändert die Platzierung. Wegbreiten, Vorführfläche und freier Tresenzugang gelten im neuen Aufbau weiter.","hint":"Trenne geänderte Mittel und unveränderte Anforderungen.","steps":"Lege zuerst fest, welchen Blickwinkel du bei den nächsten Entscheidungen weiterverfolgst.","example":"Eine Modellmessung, ein Gespräch und eine Liste der Vorgaben liefern unterschiedliche Informationen.","c":3,"sourceRefs":["M1","M2","M3"],"id":24,"l":3,"type":"story","caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","storyIndex":0,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen."},{"title":"Fünf Artikel auf zwei Möbel verteilen","scene":"Das Team entwirft neue Warenplätze. Bei L10 bleiben Muster und Schachteln nötig. P50 soll am Rad gezeigt werden. Das S20 gehört in die untere Zone. Auch Rahmentasche und Sattelüberzug bleiben Teil der Aktion.","ask":"Wie entwickelst du die neue Platzierung weiter?","options":["Ich vergleiche zwei Warenplatzskizzen und trage an beiden ein, ob L10 und P50 beim Vorführen erreichbar sind.","Ich lasse eine Kollegin Licht und Pumpe bei einer gestellten Beratung greifen und passe bestätigte Problemstellen an.","Ich reserviere die untere Regalzone für das Schloss und schließe den Vorführplatz beim Verteilen der Packungen als Lagerfläche aus.","Ich protokolliere im Modell, von welchem Warenplatz das Personal jeweils zugreift und wie es dabei den Gang nutzt.","Ich lasse eine zweite Person mit dem Fahrrad vorbeigehen und frage sie, an welchen Stellen sich das Greifen und ihre Bewegung in die Quere kommen.","Ich teile Regal und Tisch nach Funktion ein und kontrolliere jeden neuen Stellplatz auf freien Zugang, Vorführfläche und Tresen."],"consequences":["Mit denselben Zugriffspunkten kannst du zwei Warenpläne vergleichen.","Die Rückmeldung der Kollegin zeigt, welche Handgriffe im neuen Aufbau funktionieren.","Die verpflichtenden Plätze und Freiflächen bleiben bei der Verteilung geschützt.","Deine Aufzeichnungen verknüpfen die Platzierung mit dem tatsächlichen Weg.","Du erfasst eine Engstelle auch aus Sicht der vorbeigehenden Kundschaft.","Die Zuordnung gibt dem Aufbau eine klare Reihenfolge und schützt die Pflichtflächen."],"why":"Alle fünf Artikel bleiben vorgesehen. Greifbarkeit, Vorführung und freie Wege müssen zusammen funktionieren.","hint":"Greif deinen Blickwinkel aus der ersten Entscheidung wieder auf.","steps":"Prüfe, wie dein neuer Warenplatz die jeweils benötigte Nutzung ermöglicht.","example":"Eine Schachtel und ein Muster desselben Artikels müssen unterscheidbar abgelegt werden.","c":0,"sourceRefs":["M2","M3"],"id":25,"l":3,"type":"story","caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","storyIndex":1,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","branchFrom":24,"branchText":["Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast.","Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast."]},{"title":"Gleichzeitig greifen und vorbeigehen","scene":"Bei der Probe greift die Verkäuferin zum verpackten Lichtset. Genau dann nähert sich eine Person mit Fahrrad auf dem Weg zur Werkstatt. Im neuen Entwurf ist an dieser Stelle wenig Bewegungsraum.","ask":"Wie klärst du, ob und wo der Aufbau angepasst werden muss?","options":["Ich messe am kritischen Punkt den freien Weg während der Szene und markiere das Ergebnis im Plan.","Ich lasse beide beteiligten Rollen schildern, an welcher Bewegung sie hängen bleiben, und spiele die Szene mit einer Änderung erneut durch.","Ich kontrolliere die dort geltende Wegvorgabe und lege vor dem nächsten Versuch fest, wohin das Möbel bei zu knappem Abstand rückt.","Ich trage den Weg der Verkäuferin und den des Fahrrads im Modell ein und prüfe am Schnittpunkt den geringsten freien Abstand.","Ich sehe eine zweite Probe aus der Sicht der wartenden Person an und hole gezielt Rückmeldung ein, wann sie vorbeikommt.","Ich halte Hauptdurchgang und Greifweg als getrennte Anforderungen fest und teile den Umbau und anschließenden Test im Team zu."],"consequences":["Die Messung macht die vermutete Engstelle nachprüfbar.","Beide Rollen können erklären, welche Bewegung der Umbau verbessern soll.","Eine vorher vereinbarte Veränderung macht den nächsten Test zielgerichtet.","Du siehst, wo die zwei Bewegungen gleichzeitig Raum beanspruchen.","Die Rückmeldung zeigt, ob die Kundschaft die Verbindung zur Werkstatt nutzen kann.","Alle prüfen dieselben Anforderungen und kennen ihre Aufgabe beim Umbau."],"why":"Der Aufbau muss auch dann funktionieren, wenn Vorführung, Warenzugriff und eine weitere Bewegung gleichzeitig stattfinden.","hint":"Wo hat dein bisheriger Arbeitsweg eine Beobachtung, eine Rückmeldung oder eine Vorgabe gesammelt?","steps":"Untersuche dieselbe Stelle während der Nutzung, nicht nur im leeren Plan.","example":"Eine freie Linie vor der Probe belegt noch keinen freien Weg mit zwei Rädern.","c":2,"sourceRefs":["M2","M4","M5"],"id":26,"l":3,"type":"story","caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","storyIndex":2,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","branchFrom":25,"branchText":["Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast.","Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast."]},{"title":"Den Rückweg zum Tresen klären","scene":"Das Team findet eine günstigere Regalstellung. Beim Durchspielen kommt die Verkäuferin an L10. Eine neue Frage bleibt offen: Erreicht die Kundschaft den Tresen auch während einer Pumpenvorführung?","ask":"Wie ergänzt du die bisherige Prüfung?","options":["Ich markiere den Tresenzugang im neuen Plan und notiere, an welchem Punkt ich ihn bei der Pumpenvorführung geprüft habe.","Ich lasse eine Person während der Pumpenvorführung zum Tresen gehen und frage sie danach, an welcher Stelle sie warten musste oder gut durchkam.","Ich nehme den freien Tresenzugang als eigene Bedingung in die Aufbauprüfung auf und vereinbare einen Prüfschritt vor der Freigabe.","Ich prüfe mit dem Fahrradmodell, ob sich Vorführfläche und Zugang im Plan überschneiden, und halte die Stelle fest.","Ich bespreche die Variante mit der Person am Tresen und der beratenden Person und lasse beide ihren Weg gleichzeitig nachspielen.","Ich ermittle, welche Platzänderung möglich ist, wenn der Zugang versperrt ist, und weise die Verantwortung für die erneute Probe zu."],"consequences":["Du gibst dem Team einen verorteten Beleg für den Tresenzugang.","Du erfährst, was der neue Aufbau für eine Person auf dem Weg zum Tresen bedeutet.","Der Tresenzugang wird ein überprüfbarer Teil der Freigabe.","Der Plan zeigt den möglichen Konflikt zwischen Vorführung und Zugang.","Die Probe verbindet die Perspektiven am Tresen und in der Beratung.","Für einen weiteren Umbau sind ein gangbarer Schritt und seine Prüfung vereinbart."],"why":"Der Tresen bleibt fest. Eine nutzbare Bedienseite am Regal beantwortet die offene Frage zum Tresenzugang noch nicht.","hint":"Bleib beim Schwerpunkt deines bisherigen Prüfwegs.","steps":"Ergänze die fehlende Nutzung, ohne deine bisherigen Prüfpunkte wegzulassen.","example":"Licht greifen und den Tresen erreichen sind in diesem Plan unterschiedliche Aufgaben.","c":1,"sourceRefs":["M1","M2","M5"],"id":27,"l":3,"type":"story","caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","storyIndex":3,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","branchFrom":26,"branchText":["Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast.","Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast."]},{"title":"Die überarbeitete Fassung lesbar machen","scene":"Euer Aufbau ist im Modell geprüft. Die Ladenleitung bekommt den Plan ohne eure mündliche Erklärung. Das Display zeigt nur einen kleinen Ausschnitt der Zeichnung.","ask":"Wie sicherst du deinen Arbeitsweg im Plan ab?","options":["Ich ergänze die entscheidenden Messstellen und verknüpfe die Maße im Plan mit kurzen Prüfanmerkungen.","Ich lasse jemand aus dem Verkauf den Plan ohne Hilfe lesen und passe die Beschriftung nach einer konkreten Rückfrage an.","Ich trage Freiflächen und die Position des feststehenden Tresens als feste Vorgaben mit klaren Linien in den Plan ein.","Ich markiere bei der neuen Warenplatzanordnung einen überprüften Laufweg und lege mit der Legende offen, auf welchen Test er sich stützt.","Ich lasse eine Person aus der Kundschaftsrolle nur mit der Legende den Werkstattweg und den Platz zum Vorführen auseinanderhalten.","Ich beschrifte die Aufbaureihenfolge und verweise im Plan auf die Stellen, die vor der Öffnung frei gehalten werden müssen."],"consequences":["Deine Maßangaben bleiben mit dem geprüften Ort verbunden.","Ein unabhängiger Lesetest zeigt, an welcher Information der Plan verständlicher werden muss.","Die Leitung erkennt feste Grenzen und kann die Möbel passend dazu aufstellen.","Test, Weg und Planzeichen sind auch ohne mündliche Erläuterung verbunden.","Die Rückmeldung zeigt, ob die Legende die Wege ausreichend unterscheidet.","Die Aufbauhilfe verbindet Möbelpositionen mit der letzten Kontrolle."],"why":"Ein lesbarer Plan zeigt Artikelplätze, Maße und die Funktion seiner Zeichen. Die entscheidenden Änderungen müssen auffindbar bleiben.","hint":"Prüfe, was dein eigener Arbeitsweg der Ladenleitung nachvollziehbar machen soll.","steps":"Wähle eine Darstellung, die die Annahme, Messung oder Vereinbarung am richtigen Ort verankert.","example":"Eine Pfeillegende kann die Bewegungsrichtung und die Greifseite klar unterscheiden.","c":4,"sourceRefs":["M1","M4","M5"],"id":28,"l":3,"type":"story","caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","storyIndex":4,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","branchFrom":27,"branchText":["Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast.","Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast."]},{"title":"Den neuen Aufbau empfehlen","scene":"Die Ladenleitung fragt: „Können wir morgen mit einem Rollregal öffnen?“ Ihr zeigt euren Plan und nennt, was vor dem echten Aufbau noch geprüft werden muss.","ask":"Welche Empfehlung schließt deinen bisherigen Weg stimmig ab?","options":["Ich zeige den Vergleich alter und neuer Maße und begründe die Empfehlung mit dem entscheidenden Prüfergebnis.","Ich nenne, was sich durch die Rückmeldungen aus Beratung, Tresen und Kundenweg verbessert hat, und vereinbare eine kurze Rückmeldung aus dem echten Aufbau.","Ich zeige im Plan die Möbel, die Freiflächen und die noch nötige Kontrolle, damit die Leitung den Aufbau in der richtigen Reihenfolge durchführen kann.","Ich zeige die Stelle im Plan, an der sich der konfliktreiche Griffweg verbessert hat, und nenne die noch offene Messung im aufgebauten Laden.","Ich zeige, wie eine beobachtete Rollenprobe die Variante verändert hat, und benenne, wer beim Aufbau das Ergebnis noch einmal prüft.","Ich fasse zusammen, welche festen Ladenregeln erfüllt sein müssen, und lege den offenen Freigabeschritt mit zuständiger Person fest."],"consequences":["Deine Empfehlung ist am vermessenen Unterschied nachvollziehbar.","Die Beteiligten erkennen, wie ihre Beobachtungen in die Entscheidung eingeflossen sind.","Die Leitung kann unmittelbar erkennen, was aufgebaut und danach kontrolliert werden muss.","Du zeigst eine konkrete Verbesserung und hältst die Grenze des Modelltests offen.","Die Probe wird zur nachvollziehbaren Grundlage mit einer geklärten Nachkontrolle.","Die Ladenleitung weiß, unter welchen Bedingungen sie entscheiden kann."],"why":"Der Plan kann eine Empfehlung tragen. Der Test im echten Laden bleibt bei geänderten Möbeln ein eigener Schritt.","hint":"Verbinde die Empfehlung mit genau der Grundlage, die du vorher aufgebaut hast.","steps":"Zeige kurz Ergebnis, Begründung und noch offene Prüfung.","example":"Eine Empfehlung kann unter der Bedingung ausgesprochen werden, dass eine markierte Engstelle im echten Aufbau frei bleibt.","c":4,"sourceRefs":["M2","M5"],"id":29,"l":3,"type":"story","caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","storyIndex":5,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","branchFrom":28,"branchText":["Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast.","Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast."]},{"title":"Was fragt die Kundin?","scene":"Die Kundin möchte sehen, wie die Halterung eines Lichts am Lenker sitzt.","ask":"Welche Beobachtungen passen zum Block-Fall?","options":["Sie möchte den Sitz am Lenker sehen.","Sie braucht eine neue Klingel.","Die Verkäuferin holt ein Muster.","Die Verkäuferin beginnt mit der Packungsgröße.","Der Kunde bringt das Musterrad herein.","Der Kunde schaut sich zunächst ein Schloss an."],"answer":[0,2],"why":"Der Sitz der Halterung ist die Frage. Die Verkäuferin kommt mit einem Muster zurück.","hint":"Suche Frage und Reaktion.","steps":"Lies dazu die Szene am Anfang.","example":"Eine Nachfrage zum Ansetzen lässt sich direkt am Lenker zeigen.","id":30,"coreId":0,"reserveNo":1,"type":"multi","l":1,"c":2,"caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["Handlungssituation"]},{"title":"Wer kommt gleichzeitig durch?","scene":"Übungsvariante: Die Lichthalterung wird gezeigt. Gleichzeitig schiebt eine Person ihr Fahrrad zur Werkstatt. Sie bleibt vor der Beratungsstelle stehen.","ask":"Welche Informationen sollte die Ladenleitung bei der Probe festhalten?","options":["Wo beim Vorführen beide Räder stehen.","Welche Person an der Kasse bezahlen will.","Ob der Werkstattweg zu diesem Zeitpunkt nutzbar bleibt.","Wie viele Lichtsets verkauft wurden.","Wer das Vorführrad bestellt hat.","An welcher Stelle jemand auf das Vorbeigehen wartet."],"answer":[0,2,5],"why":"Die beiden Positionen, der freie Weg und der Halt helfen, die Begegnung nachzustellen.","hint":"Suche zwei gleichzeitige Bewegungen.","steps":"Vergleiche die Nutzung der Fläche vor und während der Vorführung.","example":"Ein sichtbarer Halt lässt sich mit einem Punkt im Plan festhalten.","id":31,"coreId":0,"reserveNo":2,"type":"multi","l":1,"c":2,"caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["Handlungssituation"]},{"title":"Sebastian und Christian zuordnen","scene":"Sebastian schaut dorthin, wo das Licht am Rad gezeigt wird. Christian deutet auf die verpackte Ware im Plan.","ask":"Welche Zuordnungen stimmen?","options":["Sebastian: Platz für die Vorführung.","Christian: feste Beratungsmöbel bestellen.","Sebastian: nur den Werkstattweg bemessen.","Christian: Zugriff auf die Verpackungen.","Christian: Wechsel des Sortiments.","Sebastian: neue Verkaufspreise prüfen."],"answer":[0,3],"why":"Sebastian achtet auf die Vorführung; Christian auf den Zugriff des Personals.","hint":"Prüfe, was jede Person anspricht.","steps":"Verbinde die Äußerung mit der passenden Tätigkeit.","example":"Ansetzen am Lenker und Greifen ins Regal brauchen jeweils Platz.","id":32,"coreId":1,"reserveNo":1,"type":"multi","l":1,"c":2,"caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["Handlungssituation","M2"]},{"title":"Beim Umbau beide Sichtweisen mitnehmen","scene":"Übungsvariante: Sebastian schlägt vor, dem Rad mehr Platz zu geben. Christian sieht, dass ein Tisch dadurch vor der Bedienseite landen könnte.","ask":"Was verbindet die Hinweise in der nächsten Probe?","options":["Nur die Länge des Fahrrads messen.","Beim Lichttest prüfen, ob das Rad vollständig am Vorführplatz stehen kann.","Den Tisch erst nach dem Verkauf beurteilen.","Während des Lichttests ein weiteres verpacktes Lichtset greifen lassen.","Nach dem Test allein die Gesamtfläche neu berechnen.","Vorführfläche und Zugriff jeweils an der konkreten Stelle im Plan festhalten."],"answer":[1,3,5],"why":"Die Probe macht beide Bedürfnisse sichtbar: Platz für das Rad und Zugriff auf Ware beim gleichzeitigen Vorführen.","hint":"Ordne jeder Rolle einen Testschritt zu.","steps":"Prüfe, ob die Schritte gleichzeitig möglich sind.","example":"Ein Messwert zur freien Fläche ersetzt die Greifprobe nicht.","id":33,"coreId":1,"reserveNo":2,"type":"multi","l":1,"c":2,"caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["Handlungssituation","M2"]},{"title":"Was trägt die Ware?","scene":"Auf dem Ladenplan stehen ein Rollregal, der schmale Tisch und das Vorführrad.","ask":"Welche Dinge gehören zu den beweglichen Warenträgern?","options":["Der schmale Tisch.","Das Vorführrad.","Das Rollregal.","Der freie Werkstattweg.","Die Markierung am Rad.","Der feste Tresen."],"answer":[0,2],"why":"Tisch und Rollregal tragen die Ware und sind beweglich. Das Rad dient der Vorführung.","hint":"Achte darauf, worauf Ware liegen oder stehen soll.","steps":"Trenne Möbel, Modell und freie Fläche.","example":"Ein Rollregal kann man verschieben und mit Schachteln bestücken.","id":34,"coreId":2,"reserveNo":1,"type":"multi","l":1,"c":0,"caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["Handlungssituation","M2","M6"]},{"title":"Material vor dem Probelauf sortieren","scene":"Übungsvariante: Für die Probe stellt ihr ein Rollregal und den Tisch um. Das Vorführrad wird ebenfalls bewegt. Der Tresen bleibt fest.","ask":"Welche Einträge gehören in die Spalte „bewegliche Warenträger“?","options":["Fahrrad mit Lenker.","Tisch für die Präsentation.","Markierte Stelle für den Pumpentest.","Rollregal mit Schachteln.","Fläche vor dem Beratungstresen.","Musterlicht am Rad."],"answer":[1,3],"why":"Der Tisch und das Rollregal tragen die präsentierte Ware. Beweglichkeit allein macht einen Gegenstand nicht zum Warenträger.","hint":"Prüfe Bewegung und Zweck zugleich.","steps":"Frage, ob das Objekt Verkaufsware trägt.","example":"Ein Fahrrad kann rollen und trotzdem ein Vorführmodell sein.","id":35,"coreId":2,"reserveNo":2,"type":"multi","l":1,"c":0,"caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["Handlungssituation","M2","M6"]},{"title":"Zugang und Griff auseinanderhalten","scene":"Ein Plan zeigt einen Pfeil zur Werkstatt und einen kurzen Pfeil auf die markierte lange Seite eines Regals.","ask":"Welche Angaben gehören in die Legende?","options":["Langer Pfeil: Weg zur Werkstatt.","Kurzer Pfeil: untere Regalzone.","Kurzer Pfeil: Bedienseite des Regals.","Langer Pfeil: Breite des Möbelstücks.","Kurzer Pfeil: Eingang vom Parkplatz.","Langer Pfeil: Platz für die Kasse."],"answer":[0,2],"why":"Der lange Pfeil zeigt den Weg. Der kurze Pfeil verweist auf die Seite, an der die Ware erreichbar ist.","hint":"Schau, wo die Spitze jedes Pfeils endet.","steps":"Ordne Bewegung im Gang und Greifen am Regal getrennt zu.","example":"Ein Gewinn an Genauigkeit entsteht durch „Bedienseite“ statt „Regal“.","id":36,"coreId":3,"reserveNo":1,"type":"multi","l":1,"c":4,"caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M2","M4"]},{"title":"Bei einer Drehung die Zeichen mitdrehen","scene":"Übungsvariante: Ihr dreht ein Rollregal um 90 Grad. Auf dem alten Plan zeigt der Zugriffspfeil jetzt auf seine kurze Seite. Der Werkstattpfeil zeigt weiter in den richtigen Gang.","ask":"Welche Korrektur macht den neuen Plan lesbar?","options":["Den Zugriffspfeil an die richtige lange Regalseite setzen.","Den alten Zugriffspfeil beibehalten, weil das Möbel dieselbe Größe hat.","Den Werkstattpfeil entsprechend dem tatsächlich unveränderten Weg stehen lassen.","Beide Pfeile mit „Möbel“ beschriften.","Auf die Legende ganz verzichten.","Den alten Zugriffspfeil als einzigen Werkstattpfeil verwenden."],"answer":[0,2],"why":"Mit dem Regal dreht sich seine markierte Bedienseite. Der Werkstattweg behält in dieser Skizze seine Bedeutung und Position.","hint":"Prüfe, was sich durch das Drehen verändert.","steps":"Ordne den Zeichen ihre tatsächliche Planstelle zu.","example":"Ein Zeichen für einen Gang beschreibt etwas anderes als die Griffseite eines Möbels.","id":37,"coreId":3,"reserveNo":2,"type":"multi","l":1,"c":4,"caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M2","M4"]},{"title":"Was wird woran gezeigt?","scene":"Bei Block zeigt eine Verkäuferin P50 am Ventil des bereitgestellten Fahrrads.","ask":"Was bezeichnet die Dinge treffend?","options":["P50 ist der vorgeführte Artikel.","Das Ventil ist ein Warenträger.","Das Fahrrad ist das Vorführmodell.","Der Stellplatz ist das Vorführmodell.","Das Fahrrad ist die für P50 verpackte Ware.","P50 ist der feste Tresen."],"answer":[0,2],"why":"Die Minipumpe wird vorgeführt. Das Fahrrad stellt das passende Ventil bereit und dient als Modell.","hint":"Suche Artikel und Träger der Vorführung.","steps":"Frage, was vorgeführt wird und woran.","example":"Eine Halterung wird am Lenker gezeigt. Der Lenker gehört zum Modell.","id":38,"coreId":4,"reserveNo":1,"type":"multi","l":1,"c":0,"caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M3","M6"]},{"title":"Auch ohne Fahrrad ein Muster nutzen","scene":"Übungsvariante: Das Vorführrad wird gerade für das Licht gebraucht. Die Kundin will schon vorher wissen, wie sich die leere Rahmentasche öffnen lässt.","ask":"Welche Aussagen erklären die Möglichkeiten?","options":["Für diese Frage kann ein leeres Taschenmuster benutzt werden.","Erst auf dem Fahrrad kann jede Tasche geöffnet werden.","Die Kundin kann den Verschluss am Muster anfassen.","Eine verschlossene Verkaufsschachtel zeigt die Öffnung besser als ein Muster.","Der Tisch wird durch die Tasche zum Fahrradmodell.","Das Muster kann nach der Probe erreichbar am vorgesehenen Platz bleiben."],"answer":[0,2,5],"why":"Bei der Rahmentasche reicht für die Frage zum Öffnen das leere Muster. Das Vorführrad ist dafür nicht nötig.","hint":"Achte darauf, welcher Handgriff gezeigt werden soll.","steps":"Entscheide, ob dieser Griff ein Rad oder nur das Zubehör benötigt.","example":"Eine geöffnete Tasche beantwortet Fragen zu ihrem Verschluss.","id":39,"coreId":4,"reserveNo":2,"type":"multi","l":1,"c":0,"caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M3","M6"]},{"title":"Feste Flächen finden","scene":"Der Hauptdurchgang liegt links im Plan. Die Aktionsfläche liegt daneben und beginnt bei x = 1,20 m. Der Tresen ist fest eingezeichnet.","ask":"Welche Angaben bleiben zwischen den Entwürfen gleich?","options":["Die Position des Tresens.","Die genaue Regalrichtung.","Der Beginn der Aktionsfläche bei x = 1,20 m.","Der Warenplatz der Rahmentasche in jedem Entwurf.","Die linke Lage des Hauptdurchgangs.","Der Standort des beweglichen Tischs."],"answer":[0,2,4],"why":"Tresen, Gang und Grenze sind feste Bezugspunkte. Möbel und Warenplätze können innerhalb der Regeln variieren.","hint":"Frage, was beim Umbau bewegt werden darf.","steps":"Markiere die festen Angaben im Plan.","example":"Eine unveränderte Ganggrenze eignet sich als Vergleichslinie.","id":40,"coreId":5,"reserveNo":1,"type":"multi","l":1,"c":3,"caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M2"]},{"title":"Einen gemeinsamen Planrahmen herstellen","scene":"Übungsvariante: Entwurf A zeichnet die Aktionsfläche schon ab x = 0,80 m. Entwurf B beginnt bei x = 1,20 m. Beiden liegt M1 zugrunde.","ask":"Wie stellt das Team einen vergleichbaren Rahmen her?","options":["Für beide Entwürfe die Grenze aus M1 bei x = 1,20 m eintragen.","Die Grenze zwischen beiden Werten als Kompromiss ziehen.","Unveränderte Tresenmaße in beide Skizzen übernehmen.","Das Möbel als neue Grenze festlegen.","Erst vergleichen, nachdem dieselben Pflichtflächen dargestellt sind.","Nur Entwurf A an seiner selbst gewählten Grenze beurteilen."],"answer":[0,2,4],"why":"M1 legt die Pflichtflächen fest. Die Entwürfe werden auf demselben Grundriss geprüft.","hint":"Suche die Quelle der festen x-Koordinate.","steps":"Korrigiere zuerst den Rahmen, erst danach die Möbel.","example":"Zwei Skizzen lassen sich leichter vergleichen, wenn der Gang in beiden dieselbe Breite hat.","id":41,"coreId":5,"reserveNo":2,"type":"multi","l":1,"c":3,"caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M2"]},{"title":"Eine Vorgabe im eigenen Plan umsetzen","scene":"Du bemerkst, dass du das schwere S20 auf Augenhöhe geplant hast. M3 sieht die untere Zone vor.","ask":"Welche Reaktion ist begründet?","options":["S20 unten einplanen.","Oben bleiben, weil Augenhöhe meist sichtbar ist.","Nach der Änderung den Zugriff prüfen.","Ein Schild „schwer“ oben anbringen und den Standort unverändert lassen.","Das Gewicht aus der Begründung streichen.","Den Platz für schwere Ware erst nach dem Verkauf prüfen."],"answer":[0,2],"why":"Das Gewicht verlangt die untere Zone. Nach dem Versetzen prüfst du den Griff zur Ware.","hint":"Welche Regel betrifft dieses Produkt?","steps":"Entscheide zuerst über die Höhe, danach über den freien Zugriff.","example":"Gute Sicht ersetzt keine produktspezifische Platzierungsvorgabe.","id":42,"coreId":6,"reserveNo":1,"type":"multi","l":1,"c":1,"caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M3","M5"]},{"title":"Eine passende Änderung in zweiter Runde","scene":"Übungsvariante: Das Schloss steht nach deiner ersten Änderung unten. Vor dem Regal blockiert jetzt der schmale Tisch den Zugriff.","ask":"Welche Nachbesserungen passen?","options":["Das Schloss wieder ganz nach oben stellen.","Den Tisch verschieben und den Griff in die untere Zone nachstellen.","Den neuen Engpass im Plan kennzeichnen.","Den Standort als erfüllt eintragen, weil die Regalhöhe jetzt stimmt.","Die Warengruppe im Plan umbenennen.","Die Vorgabe 'unten' beibehalten und eine gut erreichbare untere Stelle wählen."],"answer":[1,2,5],"why":"Die richtige Höhe und ein nutzbarer Zugriff müssen zusammen erfüllt sein. Eine neue Probe bestätigt die Änderung.","hint":"Finde heraus, was der erste Schritt bereits gelöst hat.","steps":"Behalte die erfüllte Vorgabe und bearbeite die neue Blockade.","example":"Ein Gegenstand kann auf der richtigen Höhe stehen und trotzdem schlecht erreichbar sein.","id":43,"coreId":6,"reserveNo":2,"type":"multi","l":1,"c":1,"caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M3","M5"]},{"title":"Ein Licht vorführen und verkaufen","scene":"Eine Person möchte das L10 am Lenker ausprobieren. Danach möchte sie eine originalverpackte Einheit kaufen.","ask":"Was braucht die Verkäuferin an den zwei Stellen?","options":["Ein Muster, das am Vorführplatz verfügbar ist.","Einen Stapel Verkaufsschachteln unmittelbar unter dem Kundinnenrad.","Einen zugänglichen Warenplatz für die Schachteln.","Ein unmarkiertes Muster im Lager.","Eine zweite Kasse am Vorführplatz.","Ein Vorführmodell im Hauptgang."],"answer":[0,2],"why":"Muster und Originalverpackung haben getrennte Funktionen. Ein freier Greifweg verbindet die beiden Tätigkeiten.","hint":"Überlege, was beim Zeigen und beim anschließenden Kauf nötig ist.","steps":"Ordne Muster und Packung ihrem Zweck zu.","example":"Die Kundschaft probiert am Muster aus und bekommt beim Kauf eine Schachtel.","id":44,"coreId":7,"reserveNo":1,"type":"multi","l":1,"c":0,"caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M3"]},{"title":"Bei der Lichtberatung nachbessern","scene":"Übungsvariante: Das Lichtmuster liegt griffbereit. Um eine Verkaufsschachtel zu nehmen, muss die Verkäuferin aber um das Vorführrad herum und eine Kundin bitten, auszuweichen.","ask":"Was verbessert die Anordnung für L10?","options":["Eine erreichbare Packung am gekennzeichneten Warenplatz bereithalten.","Das Muster zum Packungslager bringen und die Vorführung am Rad streichen.","Den Griff zur Schachtel während einer erneuten Lichtprobe testen.","Eine Packung auf den Werkstattweg stellen.","Das Muster am Vorführplatz lassen und den getrennten Packungsplatz besser zugänglich machen.","Die ersten Packungen unbeschriftet am Tresen sammeln."],"answer":[0,2,4],"why":"Die Stärke des ersten Entwurfs bleibt erhalten. Nun braucht die verpackte Ware einen nutzbaren Zugriff während derselben Beratung.","hint":"Unterscheide den schon funktionierenden Musterplatz und das neue Zugriffsproblem.","steps":"Ändere gezielt den Warenplatz und prüfe ihn im Ablauf.","example":"Wenn jemand ausweichen muss, lohnt ein Blick auf die Lage der Bedienseite.","id":45,"coreId":7,"reserveNo":2,"type":"multi","l":1,"c":0,"caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M3"]},{"title":"Produkte am Nutzungsort erkennen","scene":"Die Kundschaft stellt kurze Fragen zu ihrem Fahrradzubehör.","ask":"Welche Frage passt zum angegebenen Artikel?","options":["L10: Kann ich die Lampe wieder von der Halterung lösen?","T30: Kann ich den Überzug am Sattel testen?","S20: Wie groß ist der Bügel?","R40: Wie setze ich den Pumpenkopf an?","P50: Wie schnell komme ich an Kleinteile?","L10: Wie schwer ist das Bügelschloss?"],"answer":[0,2],"why":"Lösen von der Halterung betrifft das Licht. Bügelgröße ist eine Frage zum Schloss.","hint":"Achte auf Stichwörter für Bauteil oder Handlung.","steps":"Verbinde jede Frage im Kopf mit einem Fahrradteil.","example":"Am Bügel erkennt man das Bügelschloss.","id":46,"coreId":8,"reserveNo":1,"type":"multi","l":1,"c":0,"caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M3"]},{"title":"Muster für drei Fragen vorbereiten","scene":"Übungsvariante: Nacheinander fragen Kunden nach einem trockenen Sitzüberzug zum Testen, der Bedienung der Pumpe und dem Zugang zu Kleinteilen im Zubehör.","ask":"Welche Vorbereitung passt?","options":["Ein R40-Muster für die Frage am Sattel bereitlegen.","Das Bügelschloss für die Ventilfrage bereithalten.","Die Minipumpe P50 am Vorführrad mit Ventil zeigen können.","Für Kleinteile eine leere Rahmentasche öffnen lassen.","Das Lichtset als Überzug für den Sattel vorführen.","Die Rahmentasche zum Aufpumpen des Reifens einsetzen."],"answer":[0,2,3],"why":"Sitzprobe, Pumpendemo und Griff zu Kleinteilen benötigen jeweils das passende Zubehör.","hint":"Beachte die Handlung hinter jedem Kundenwunsch.","steps":"Ordne jedem Wunsch ein Produkt und einen Probeschritt zu.","example":"Kleinteile lassen sich an einer leeren Tasche beispielhaft prüfen.","id":47,"coreId":8,"reserveNo":2,"type":"multi","l":1,"c":0,"caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M3"]},{"title":"Zentimeter im Maßstab 1:20","scene":"Die Tiefenlinie misst im Laden 4,00 m. Du zeichnest im Maßstab 1:20.","ask":"Welche Angaben gehören zur Rechnung?","options":["4,00 m sind 400 cm.","400 cm werden mit 20 multipliziert.","400 cm geteilt durch 20 ergeben 20 cm im Plan.","4,00 m sind 40 cm.","Die Tiefenlinie ist im Plan 2 cm lang.","Die Tiefenlinie ist im Plan 80 cm lang."],"answer":[0,2],"why":"Für gleiche Einheiten wandelst du Meter in Zentimeter um. Planmaß ist 400 cm ÷ 20.","hint":"Schreibe zuerst die Ladenlänge in Zentimetern.","steps":"Verkleinere erst danach mit dem Maßstab.","example":"100 cm im Laden wären im Plan 5 cm.","id":48,"coreId":9,"reserveNo":1,"type":"multi","l":1,"c":3,"caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1"]},{"title":"Ein Maß prüfen, bevor du es einzeichnest","scene":"Übungsvariante: Eine Vergleichsskizze soll eine 3,60 m breite Teilfläche und eine 0,80 m lange Tischkante im Maßstab 1:20 zeigen.","ask":"Welche Planmaße stimmen?","options":["Die Teilfläche ist 18 cm breit.","Die Tischkante ist 16 cm lang.","Die Tischkante ist 4 cm lang.","Die Teilfläche ist 72 cm breit.","Die Tischkante ist 0,4 cm lang.","Die Teilfläche ist 1,8 cm breit."],"answer":[0,2],"why":"360 cm ÷ 20 = 18 cm. 80 cm ÷ 20 = 4 cm.","hint":"Beginne mit 360 cm und 80 cm.","steps":"Rechne die beiden Längen einzeln aus.","example":"2 cm auf dem Papier entsprechen 40 cm im Laden.","id":49,"coreId":9,"reserveNo":2,"type":"multi","l":1,"c":3,"caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1"]},{"title":"Ein Planzeichen erklären","scene":"Ein anderes Team sieht Pfeile im Grundriss und Schachteln mit Artikelcodes im Regal.","ask":"Welche Angaben braucht es zum Lesen?","options":["Eine Legende für die Pfeile.","Eine unbeschriftete Farbliste.","Die Produktcodes an ihren Warenplätzen.","Nur den Namen des zeichnenden Teams.","Ein Bild aus dem Laden ohne Bezug zur Skizze.","Eine Preisliste für nicht eingezeichnete Artikel."],"answer":[0,2],"why":"Legende und Produktcodes verbinden Zeichen mit Weg oder Warenplatz. So kann jemand die Skizze ohne Nachfragen lesen.","hint":"Was sieht jemand, der beim Zeichnen nicht dabei war?","steps":"Prüfe, ob Zeichen und Produktplatz verständlich sind.","example":"Ein Pfeil am Regal kann für den Zugriff stehen, wenn das in der Legende erklärt wird.","id":50,"coreId":10,"reserveNo":1,"type":"multi","l":1,"c":4,"caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M4","M5"]},{"title":"Eine Skizze per Bildschirm prüfen lassen","scene":"Übungsvariante: Beim Teilen sieht die Prüfgruppe nur den Ausschnitt mit dem Lichtregal. Sie findet weder die kleinste Wegbreite noch erkennt sie die Bedienseite.","ask":"Welche Ergänzungen machen genau diesen Ausschnitt nutzbar?","options":["Das Maß an die engste Stelle schreiben.","Einen Fotoeffekt statt der Maßangabe nutzen.","Die Bedienseite direkt mit einem Zeichen und einer kurzen Erklärung markieren.","Die Regalhöhe statt der Wegbreite eintragen.","Eine unverbundene Zahl ganz oben auf der Seite eintragen.","Den Lichtwarenplatz mit L10 beschriften."],"answer":[0,2,5],"why":"Maß, Zugriff und Produktcode gehören an ihre konkreten Stellen. Damit ist der Ausschnitt für die Prüfgruppe verständlich.","hint":"Erschließe, welche Informationen im Ausschnitt fehlen.","steps":"Platziere jede Information direkt am zugehörigen Objekt oder Weg.","example":"Ein Maß an einer Engstelle ist schneller zuzuordnen als eine Zahl neben dem Titel.","id":51,"coreId":10,"reserveNo":2,"type":"multi","l":1,"c":4,"caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M4","M5"]},{"title":"Eine Störung auf dem Plan festhalten","scene":"Du beobachtest, dass das Vorderrad vor dem Rollregal steht und die Verkäuferin nicht greifen kann.","ask":"Welche erste Reaktion bringt dich weiter?","options":["Die Stelle von Fahrrad und blockierter Bedienseite markieren.","Die Farbe des Fahrrads ändern.","Die Position im Aufbau mit dem gezeichneten Plan abgleichen.","Die Problemstelle nur mündlich erwähnen und nicht wiederholen.","Die Packungen aus dem Plan löschen.","Den Test als erledigt abhaken."],"answer":[0,2],"why":"Die genaue Stelle ist Ausgangspunkt für eine begründete Änderung und eine erneute Probe.","hint":"Was blockiert den Zugriff genau?","steps":"Markiere beides: Rad und Zugriffsstelle.","example":"Ein Kreuz im Plan zeigt eindeutig, wo der Greifversuch stockte.","id":52,"coreId":11,"reserveNo":1,"type":"multi","l":1,"c":1,"caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M4","M5"]},{"title":"Eine zweite Probe sinnvoll nutzen","scene":"Übungsvariante: Du drehst das Regal so, dass die Verkäuferin wieder an die Schachteln kommt. Beim zweiten Test ist am Beratungstresen ein Engpass sichtbar.","ask":"Welche Schritte passen zur Weiterarbeit?","options":["Die erste Verbesserung des Griffs anerkennen und den neuen Engpass gesondert prüfen.","Den letzten Test verwerfen, weil eine Frage schon geklärt war.","Eine Änderung suchen, die Greifweg und Tresenzugang offen hält.","Nur die alte Blockade notieren.","Den Tresen im Plan löschen, weil er stört.","Nach der nächsten Änderung beide Wege gleichzeitig testen."],"answer":[0,2,5],"why":"Eine Änderung kann ein Problem lösen und ein anderes schaffen. Markiere den neuen Konflikt und sichere beide Funktionen in einer weiteren Probe.","hint":"Sammle, was jetzt gelingt und was noch stört.","steps":"Bewahre die erreichte Verbesserung und prüfe die neue Schwachstelle.","example":"Ein freies Regal beantwortet nicht die Frage, ob der Tresen erreichbar bleibt.","id":53,"coreId":11,"reserveNo":2,"type":"multi","l":1,"c":1,"caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M4","M5"]},{"title":"Mindestmaße einzeln prüfen","scene":"Die Vorführung braucht 2,00 m × 1,30 m. Übungsvariante: Ein abgestecktes Rechteck misst 2,05 m × 1,30 m.","ask":"Was lässt sich zu diesen Maßen sagen?","options":["Die Länge reicht aus.","Die Breite unterschreitet die Vorgabe um 5 cm.","Die Breite erfüllt die Vorgabe genau.","Das Rechteck kann nur für ein Verkaufsregal verwendet werden.","Die beiden Seiten sind in diesem Fall jeweils zu lang.","Die Form ist nur geeignet, wenn beide Seiten gleich lang sind."],"answer":[0,2],"why":"2,05 m ist mehr als 2,00 m. Die Breite erreicht genau 1,30 m.","hint":"Prüfe zwei Seiten statt nur der Fläche.","steps":"Vergleiche die längere und kürzere Seite mit ihrem Mindestmaß.","example":"2,00 m und 1,30 m dürfen genau erreicht werden.","id":54,"coreId":12,"reserveNo":1,"type":"multi","l":2,"c":3,"caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2"]},{"title":"Vorführplatz nach einer Drehung","scene":"Übungsvariante: Entwurf A hat 1,32 m in x-Richtung und 2,05 m in y-Richtung frei. B hat 2,20 m in x-Richtung und 1,23 m in y-Richtung. Andere Bereiche sind frei.","ask":"Welche Aussagen treffen zu?","options":["A kann wegen der Lage seiner langen Seite nie passen.","A erfüllt beide Mindestmaße.","Bei B fehlen 7 cm an der kurzen Seite.","Die größere Länge von B reicht als Ausgleich aus.","A ist an seiner kurzen Seite 2 cm breiter als nötig.","B ist um 23 cm schmaler als erlaubt."],"answer":[1,2,4],"why":"A ist lang und breit genug. In B beträgt die kurze Seite nur 1,23 m, also fehlen 0,07 m. Die Richtung der langen Seite darf wechseln.","hint":"Ordne zuerst jedem Rechteck seine lange Seite zu.","steps":"Vergleiche 2,05 m und 2,20 m mit 2,00 m, danach die kürzeren Maße.","example":"Eine Drehung ändert die Lage, nicht die Seitenlängen.","id":55,"coreId":12,"reserveNo":2,"type":"multi","l":2,"c":3,"caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2"]},{"title":"Ein Mindestmaß auf dem Papier","scene":"Der Weg braucht 0,90 m Breite. Du rechnest für eine Zeichnung im Maßstab 1:20.","ask":"Welche Aussagen passen?","options":["0,90 m sind 90 cm im Laden.","Auf dem Papier reichen dafür 0,45 cm.","Die Mindestbreite im Plan ist 4,5 cm.","90 cm sind im Plan 18 cm.","0,90 m entsprechen 900 cm im Laden.","Im Maßstab 1:20 gilt eine Mindestbreite von 20 cm auf dem Papier."],"answer":[0,2],"why":"0,90 m = 90 cm. Geteilt durch 20 sind das 4,5 cm in der Zeichnung.","hint":"Rechne zunächst Meter in Zentimeter um.","steps":"Teile erst danach das Ladenmaß durch 20.","example":"Ein 1,00 m breiter Weg erscheint 5 cm breit.","id":56,"coreId":13,"reserveNo":1,"type":"multi","l":2,"c":3,"caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M4"]},{"title":"Drei Stellen eines Weges prüfen","scene":"Übungsvariante: Auf eurem Plan im Maßstab 1:20 misst der Weg 5,1 cm, 4,4 cm und 4,7 cm. Die Vorgabe beträgt 0,90 m.","ask":"Welche Folgerungen stimmen?","options":["Die Stelle mit 4,4 cm ist nur 0,88 m breit.","Der Mittelwert genügt als Beleg dafür, dass der ganze Weg breit genug ist.","An der engsten Stelle fehlen im Laden 2 cm.","Die Stelle mit 5,1 cm misst tatsächlich 0,51 m.","Die Engstelle muss nach einer Änderung nochmals gemessen werden.","Alle drei Stellen liegen unter der Mindestbreite."],"answer":[0,2,4],"why":"4,4 cm mal 20 sind 88 cm. Es fehlen 2 cm. Die Mindestbreite muss an jeder Stelle eingehalten werden.","hint":"Suche die kleinste Planbreite.","steps":"Multipliziere ihren Zentimeterwert mit 20 und vergleiche mit 90 cm.","example":"Auch ein breiter Anfang gleicht eine Engstelle im Verlauf des Weges nicht aus.","id":57,"coreId":13,"reserveNo":2,"type":"multi","l":2,"c":3,"caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M4"]},{"title":"Das Rollregal ausschneiden","scene":"Das Rollregal misst 1,00 m × 0,40 m. Du bereitest ein Papiermodell im Maßstab 1:20 vor.","ask":"Welche Aussagen helfen beim Zuschnitt?","options":["Die Seiten am echten Regal messen 100 cm und 40 cm.","Der Zuschnitt misst 5 cm × 2 cm.","Der Zuschnitt misst 2 cm × 1 cm.","Die Druckvorlage muss die Maße mit 20 multiplizieren.","Die 0,40 m werden zu 0,4 cm auf dem Papier.","Der Zuschnitt misst 20 cm × 8 cm."],"answer":[0,1],"why":"100 cm ÷ 20 = 5 cm. 40 cm ÷ 20 = 2 cm.","hint":"Wandle Meter in Zentimeter um.","steps":"Rechne jede Seite getrennt um.","example":"Die Fläche wird aus den beiden verkleinerten Seiten gezeichnet.","id":58,"coreId":14,"reserveNo":1,"type":"multi","l":2,"c":3,"caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M4"]},{"title":"Zugriffsweg und Regal im Modell kontrollieren","scene":"Übungsvariante: Du zeichnest ein Rollregal von 1,00 m × 0,40 m. Daneben markierst du einen 0,90 m breiten freien Weg. Das Modell hat Maßstab 1:20.","ask":"Welche Prüfungen stimmen?","options":["Das Regalmodell braucht 5 cm × 2 cm.","Der freie Weg ist im Modell mindestens 4,5 cm breit.","Eine Regalkante von 10 cm auf Papier zeigt genau 1,00 m Ladenmaß.","Die Wegmarkierung soll 2,75 cm breit sein.","Ein 4,0 cm breiter Modellweg reicht für 0,90 m aus.","Regal und Weg müssen jeweils mit demselben Maßstab gezeichnet werden."],"answer":[0,1,5],"why":"Das Regal misst im Modell 5 × 2 cm. 90 cm Wegbreite ergeben 4,5 cm. Nur ein einheitlicher Maßstab macht den Test aussagekräftig.","hint":"Trenne die Seiten des Regals von der Breite des Weges.","steps":"Teile 100, 40 und 90 jeweils durch 20.","example":"Der 4,0 cm breite Weg würde 0,80 m im Laden darstellen.","id":59,"coreId":14,"reserveNo":2,"type":"multi","l":2,"c":3,"caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M4"]},{"title":"Eine feste Grenze im Plan erkennen","scene":"Übungsvariante: Der Hauptdurchgang endet bei x = 1,20 m. Dein Regal reicht von x = 1,10 m bis x = 2,10 m und liegt in y-Richtung auf Höhe der Aktionsfläche.","ask":"Was fällt bei der Prüfung auf, und welche Korrektur ist nötig?","options":["Die linke Regalkante liegt 0,10 m im Gang.","Die rechte Kante bestimmt, ob das ganze Regal richtig steht.","Das Regal aus dem Hauptdurchgang verschieben.","Die feste Ganggrenze um 10 cm zur Seite verlegen.","Nur die Bezeichnung des Regals ändern.","Die Bedienseite einfach entfernen."],"answer":[0,2],"why":"Der Bereich von x = 1,10 bis x = 1,20 m überschneidet den Hauptdurchgang. Der Warenträger muss vollständig auf der Aktionsfläche stehen.","hint":"Sieh auf die linke Regalkante.","steps":"Prüfe die Strecke zwischen 1,10 m und 1,20 m.","example":"Der Mittelpunkt des Regals verrät nicht, ob eine Kante im Gang steht.","id":60,"coreId":15,"reserveNo":1,"type":"multi","l":2,"c":1,"caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M2"]},{"title":"Beim Versetzen die Bedienseite mitprüfen","scene":"Übungsvariante: Du verschiebst ein teilweise im Hauptdurchgang stehendes Regal vollständig auf die Aktionsfläche. Eine zweite Skizze zeigt, dass sein Zugriff danach nur über einen 0,82 m breiten Weg möglich wäre.","ask":"Welche Reaktionen verbessern deinen Entwurf?","options":["Die Korrektur als abgeschlossen melden, weil der Gang frei ist.","Merken, dass der Hauptdurchgang frei geworden ist.","Die 0,82 m mit der Vorgabe von 0,90 m vergleichen.","Eine neue Stellung suchen und die Bedienseite erneut prüfen.","Den 0,82-m-Weg mit dem freien Hauptgang verrechnen.","Das neue Standortproblem durch Umbenennen der Bedienseite lösen."],"answer":[1,2,3],"why":"Die erste Überschneidung ist behoben. Für den Zugriff fehlen aber 8 cm. Die weitere Änderung muss beide Anforderungen sichern.","hint":"Was hat dein erster Umbau gelöst, und welche Vorgabe ist neu betroffen?","steps":"Prüfe Gang und Greifweg als getrennte Bedingungen.","example":"Ein erfüllter Pflichtpunkt ersetzt keinen anderen.","id":61,"coreId":15,"reserveNo":2,"type":"multi","l":2,"c":1,"caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M2"]},{"title":"Zwei Wegbreiten schnell vergleichen","scene":"Übungsvariante: Der Vorführplatz passt in beiden Entwürfen. Beim Vorführen bleiben zur Bedienseite in A 0,88 m und in B 0,96 m frei.","ask":"Welche Aussagen stimmen?","options":["A erfüllt die Mindestbreite 0,90 m nicht.","A reicht, weil nur 2 cm fehlen.","B erfüllt die Mindestbreite für den Greifweg.","B ist damit automatisch an jeder Stelle des Ladens getestet.","A dürfte den kleineren Abstand durch ein größeres Rad ausgleichen.","Die Mindestbreite gilt ausschließlich vor der Vorführung."],"answer":[0,2],"why":"A unterschreitet die Regel um 2 cm. B erfüllt diesen Messpunkt. Andere Wege und Greifbarkeit bleiben Teil der Probe.","hint":"Vergleiche jeden Wert mit 0,90 m.","steps":"Halte Maßprüfung und praktische Probe getrennt.","example":"Ein passendes Maß beweist nur die Eigenschaft, die du gemessen hast.","id":62,"coreId":16,"reserveNo":1,"type":"multi","l":2,"c":2,"caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M5"]},{"title":"Zwei Aufbauvorschläge vergleichen","scene":"Übungsvariante: A hat am Vorführplatz 2,05 m × 1,27 m und einen 1,00 m breiten Greifweg. B hat 2,00 m × 1,35 m und einen 0,91 m breiten Greifweg. Beide halten Tresenzugang und Hauptdurchgang frei.","ask":"Was ist die begründete Empfehlung fürs Team?","options":["A ist geeignet, weil der breitere Greifweg jede knappe Fläche ausgleicht.","B hält die genannten Pflichtmaße ein.","A unterschreitet das kurze Mindestmaß am Vorführplatz um 0,03 m.","A ist wegen der langen Seite insgesamt zulässig.","B eignet sich nach den Angaben für die praktische Vorführprobe.","B unterschreitet die Vorgabe für den Greifweg um 0,01 m."],"answer":[1,2,4],"why":"Die kurze Seite von A müsste 1,30 m betragen. B erfüllt mit mindestens 2,00 × 1,30 m und 0,90 m freiem Weg beide Vorgaben.","hint":"Prüfe in beiden Plänen dieselben zwei Maßarten.","steps":"Vergleiche Vorführplatz und Weg getrennt und wähle dann die Probe.","example":"Gleiche Kriterien sind auch dann sinnvoll, wenn jeder Plan eine andere Stärke hat.","id":63,"coreId":16,"reserveNo":2,"type":"multi","l":2,"c":2,"caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M5"]},{"title":"Tasche und Schloss passend anbieten","scene":"Auf dem Tisch liegt ein T30-Muster. Ein Teammitglied will das schwere S20 dazulegen, damit beide gleich gut sichtbar sind.","ask":"Was ist bei Block fachlich passend?","options":["Das leere Taschenmuster so platzieren, dass man es öffnen kann.","Das Schloss mit der Rahmentasche an derselben Stelle auf Augenhöhe zeigen.","Das Bügelschloss in der unteren Regalzone bereitstellen.","Die Tasche als Muster am Sattel befestigen.","Alle leichten Muster in verschlossenen Kartons lassen.","Das Schloss in die Werkstatt verlegen."],"answer":[0,2],"why":"T30 soll ausprobiert werden können. S20 bekommt wegen seines Gewichts einen erreichbaren Platz unten im Regal.","hint":"Beachte den vorgesehenen Handgriff je Artikel.","steps":"Prüfe bei der Tasche das Öffnen und beim Schloss die vorgegebene Regalzone.","example":"Gute Gruppierung richtet sich auch danach, was die Kundschaft mit dem Artikel tun will.","id":64,"coreId":17,"reserveNo":1,"type":"multi","l":2,"c":0,"caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M3"]},{"title":"Zwei Beratungsanlässe auf einer Fläche einplanen","scene":"Übungsvariante: Ein Team möchte einen Bereich für Fragen am Rad und einen für das Anfassen von Zubehör kennzeichnen. Vorhanden sind alle fünf Aktionsartikel.","ask":"Welche Zuordnungen enthalten eine fachliche Begründung?","options":["P50 griffbereit nahe der Vorführung, weil der Ventilanschluss gezeigt wird.","S20 oben neben L10, weil beide Produktcodes eine Zahl enthalten.","T30 mit leerem Muster zum Öffnen auslegen.","R40 am Rad zeigen und die Verpackungen erreichbar lassen.","Alle Muster auf dem Werkstattweg ablegen.","Die Rahmentasche am Ventil befestigen, um die Pumpe zu erklären."],"answer":[0,2,3],"why":"P50 wird am Ventil gezeigt, R40 kann am Sattel ausprobiert werden, T30 lässt sich am leeren Muster öffnen. Die Wege bleiben frei.","hint":"Welche Kundenhandlung soll bei jedem Produkt möglich sein?","steps":"Leite aus der Kundenfrage den jeweils passenden Waren- oder Musterplatz ab.","example":"Eine Produktnummer ist eine Kennzeichnung, kein Grund für dieselbe Regalzone.","id":65,"coreId":17,"reserveNo":2,"type":"multi","l":2,"c":0,"caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M3"]},{"title":"Rollen und Wege vor der Probe klären","scene":"Eine Kundin hält ihr Rad, die Verkäuferin führt L10 vor und eine andere Person will zur Werkstatt.","ask":"Was sollte jemand im Probeablauf beobachten?","options":["Ob die zweite Person den Werkstattweg nutzen kann.","Ob die Verkäuferin zum verpackten Lichtset greifen kann.","Ob die Kundin schon für Zubehör bezahlt hat.","Ob sich die Werkstatt später telefonisch erreichen lässt.","Ob die Schuhe der Testpersonen zusammenpassen.","Ob der Preis groß genug gedruckt ist."],"answer":[0,1],"why":"Die Probe konzentriert sich darauf, ob Beratung, Warenzugriff und Durchgang gleichzeitig funktionieren.","hint":"Gehe die Bewegungen aller Rollen kurz durch.","steps":"Markiere, wann jemand am Rad, am Regal oder am Gang steht.","example":"Zwei getrennte Tests ohne Begegnung können eine spätere Engstelle übersehen.","id":66,"coreId":18,"reserveNo":1,"type":"multi","l":2,"c":2,"caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M4","M5"]},{"title":"Eine dritte Bewegung im Test berücksichtigen","scene":"Übungsvariante: Während der Pumpendemo kommt jemand zum Beratungstresen. Zeitgleich möchte die Verkäuferin zur Packung greifen, und auf dem Hauptdurchgang schiebt eine Person ein Rad vorbei.","ask":"Welche Protokolleinträge helfen der Ladenleitung?","options":["Zeitpunkt und Ort des Griffs zur Ware.","Welche Person aus der Gruppe zuerst vorgeschlagen hat, das Rollenspiel zu machen.","Ob der Zugang zum Tresen während der Vorführung nutzbar bleibt.","Ob das Fahrrad am Hauptdurchgang ohne Ausweichen vorbeikommt.","Wie lange das Handzeichen zum Start dauert.","Die Wegbreite nur im leeren Laden vor dem Rollenspiel."],"answer":[0,2,3],"why":"Drei gleichzeitige Tätigkeiten zeigen, ob die Fläche im Betrieb funktioniert. Die Beteiligten prüfen Zugriff, Tresen und Durchgang.","hint":"Unterscheide Personen, Orte und Handlungen.","steps":"Spiele die Wege zeitgleich nach und halte Engstellen konkret fest.","example":"Ein Ort und eine beobachtete Bewegung ergeben einen brauchbaren Prüfhinweis.","id":67,"coreId":18,"reserveNo":2,"type":"multi","l":2,"c":2,"caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M4","M5"]},{"title":"Eine Pumpenprobe vorbereiten","scene":"Übungsvariante: Am Vorführplatz liegen eine Rahmentasche T30, ein Lichtmuster L10 und die Minipumpe P50 bereit. Eine Kundin möchte am Vorführrad selbst erproben, wie sie eine Pumpe ansetzt.","ask":"Was sollte die Verkäuferin vor dem ersten Handgriff vorbereiten oder prüfen?","options":["P50 von Licht und Tasche unterscheiden und für die Probe bereitlegen.","Die Rahmentasche am Rahmen befestigen und ihren Verschluss mit der Ventilart vergleichen.","Am Vorführrad das Sclaverandventil zeigen, an dem die Kundin den Pumpenkopf ansetzen kann.","Zum Test ein verpacktes Lichtset öffnen und dessen Halterung am Ventil festmachen.","Das Fahrrad so am Vorführplatz ausrichten, dass die Kundin am Ventil arbeiten kann und der Hauptdurchgang frei bleibt.","Die Größe der Lichtverpackung als Nachweis verwenden, dass P50 am Ventil passt."],"answer":[0,2,4],"why":"Für den Handgriff braucht die Kundin P50, das richtige Ventil am Vorführrad und ausreichend Platz in der Vorführzone. Licht und Tasche beantworten andere Beratungsfragen.","hint":"Welcher Artikel benutzt ein Ventil, und wo kann die Kundin an das Ventil heran?","steps":"Wähle zuerst den passenden Artikel aus. Prüfe danach das Vorführrad und den freien Platz am Ventil.","example":"Eine Minipumpe wird am Ventil angesetzt. Eine Lichthalterung sitzt am Lenker.","id":68,"coreId":19,"reserveNo":1,"type":"multi","l":2,"c":0,"caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M3","M5"]},{"title":"Vom Vorführrad zum mitgebrachten Rad","scene":"Übungsvariante: Eine Kundin bringt ein Rad mit einem anderen, noch nicht bestimmten Ventil. Ihr habt P50 am Sclaverandventil des Vorführrads gezeigt.","ask":"Wie geht die Beratung fachlich weiter?","options":["Den Ventiltyp am mitgebrachten Rad klären.","Den gezeigten Erfolg ohne Prüfung auf alle Ventile übertragen.","Den Warenplatz für P50 erreichbar halten, falls die Kundin die Ware sehen will.","Bei einer weiteren Probe am vorgesehenen Platz bleiben und Wege offen halten.","Den Pumpenkopf mit Kraft auf das unbekannte Ventil drücken.","Die nächste Probe vor dem Eingang im Hauptdurchgang durchführen."],"answer":[0,2,3],"why":"Der erste Test belegt den Handgriff am Sclaverandventil. Vor einer Aussage zum mitgebrachten Rad wird dessen Ventil geprüft.","hint":"Welche Angabe ist sicher und welche fehlt noch?","steps":"Trenne die gezeigte Bedienung von der Eignungsprüfung am Kundinnenrad.","example":"Ein gezeigter Handgriff kann richtig sein, auch wenn ein anderes Rad eine eigene Prüfung braucht.","id":69,"coreId":19,"reserveNo":2,"type":"multi","l":2,"c":0,"caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M3","M5"]},{"title":"Einen fehlenden Eintrag ergänzen","scene":"An der schmalsten Stelle ist zwar ein Maßstrich eingezeichnet, die Zahl fehlt. Der Zugriff aufs Regal ist als Pfeil markiert.","ask":"Was sollte vor der Weitergabe ergänzt werden?","options":["Die tatsächliche Breite am Maßstrich eintragen.","Die Farbe des Mantels der Testkundin notieren.","Den Pfeil in der Legende als Bedienseite erklären.","Anstelle des Wegmaßes den Preis des Lichtsets schreiben.","Alle Maßstriche als Produktplätze ausweisen.","Den Zugriffspfeil verschieben, bis er möglichst dekorativ aussieht."],"answer":[0,2],"why":"Maßwert und Legende helfen der prüfenden Person, Breite und Griffseite richtig zu lesen.","hint":"Was soll die empfangende Person nachprüfen können?","steps":"Ergänze fehlende Zahl und Bedeutung direkt im Plan.","example":"Ein freier Weg wird erst prüfbar, wenn die Maßlinie einen Wert hat.","id":70,"coreId":20,"reserveNo":1,"type":"multi","l":2,"c":4,"caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M3","M4","M5"]},{"title":"Mehrere Artikelplätze lesbar unterscheiden","scene":"Übungsvariante: Ein Rollenversuch ist dokumentiert, aber auf dem Foto der Skizze zeigen dieselben Kreise sowohl Warenplätze als auch Haltepunkte von Fahrrädern.","ask":"Wie überarbeitet das Team die Darstellung?","options":["Für Fahrradhalte und Warenplätze verschiedene Zeichen benutzen.","Alle Kreise mit „Block“ kennzeichnen.","Mit der Legende erklären, was ein Zeichen jeweils bedeutet.","P50 und L10 an ihren konkreten Warenplätzen eintragen.","Die Kreise nur insgesamt vergrößern.","Pro Fahrradhalt eine neue Waren-Plannummer vergeben und beide weiterhin gleich darstellen."],"answer":[0,2,3],"why":"Getrennte Symbole und eine klare Legende machen den Rollenversuch klar. Produktcodes helfen zusätzlich beim Finden der Ware.","hint":"Unterscheide einen Ort für Ware und einen vorübergehenden Halt.","steps":"Nutze für verschiedene Funktionen verschiedene Zeichen.","example":"Ein Symbol ist hilfreich, wenn es im Plan eine eindeutige Aufgabe hat.","id":71,"coreId":20,"reserveNo":2,"type":"multi","l":2,"c":4,"caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M3","M4","M5"]},{"title":"Eine konkrete Rückmeldung verwerten","scene":"Die Testperson sagt: „Das Rad steht vor dem Regal. Ich komme nicht an die Lichtschachtel.“","ask":"Welche Aussagen führen zu einem besseren Entwurf?","options":["Die blockierte Stelle vor dem Regal einzeichnen.","Rückmelden, dass das Regal immerhin gut sichtbar ist.","Überprüfen, ob das Rad am Vorführplatz anders stehen kann.","Die Lichtschachteln tiefer ins Regal schieben.","Die Rückmeldung als Wunsch nach einem neuen Produkt eintragen.","Den Versuch ohne Vorführrad als abgeschlossen bewerten."],"answer":[0,2],"why":"Die Rückmeldung nennt Ort und betroffenes Greifen. Eine neue Radposition kann das Problem lösen, wenn Vorführplatz und Wege frei bleiben.","hint":"Welche Tätigkeit wurde konkret verhindert?","steps":"Prüfe die Ursache und wähle dazu eine Änderung.","example":"Bewegungsraum lässt sich erst beurteilen, wenn das Rad im Versuch wirklich am Platz steht.","id":72,"coreId":21,"reserveNo":1,"type":"multi","l":2,"c":1,"caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M4","M5"]},{"title":"Nach einer Änderung nochmals nachfragen","scene":"Übungsvariante: Nach Kritik ist die Schachtel jetzt gut erreichbar. Eine Verkäuferin meldet in der Probe, beim Griff stoße ihr Vorführrad fast an eine wartende Person.","ask":"Welche nächsten Schritte sind begründet?","options":["Die Rückmeldung mit Zeitpunkt und Position aufnehmen.","Den weiteren Test abbrechen, weil der Griff zur Ware gelungen ist.","Die geänderte Anordnung mit wartender Person nochmals testen.","Die Verkäuferin bitten, im Hauptgang vorzuführen.","Die Abstände während desselben Ablaufs überprüfen.","Nur das Feedback aus der ersten Probe berücksichtigen."],"answer":[0,2,4],"why":"Warenzugriff und sichere Nutzung müssen beide funktionieren. Die nächste Probe nimmt die wartende Person als Teil der Szene auf.","hint":"Was entdeckst du erst bei gleichzeitigem Greifen und Warten?","steps":"Halte die erfüllte Anforderung fest und prüfe die neue Schwachstelle am Ort.","example":"Eine konkrete Rückfrage kann lauten: Wo stand die wartende Person genau?","id":73,"coreId":21,"reserveNo":2,"type":"multi","l":2,"c":1,"caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M4","M5"]},{"title":"Eine gemeinsame Probe auswählen","scene":"Zwei Teams wollen erklären, welcher Aufbau sich für eine Lichtberatung eignet. Ein Team misst vorher, das andere beobachtet nur beim Vorführen.","ask":"Wie werden die Ergebnisse vergleichbarer?","options":["Bei beiden Varianten denselben Lichtgriff am Vorführrad nachspielen.","Bei jeder Variante nur ihre beste Eigenschaft prüfen.","In beiden Varianten die Wegbreite an der jeweils engsten Stelle notieren.","Bei einem Aufbau die Uhrzeit und beim anderen den Produktcode vergleichen.","Die Ergebnisse nur nach der Reihenfolge der Vorstellungen sortieren.","Den ungeprüften Aufbau automatisch als gleichwertig behandeln."],"answer":[0,2],"why":"Gleiche Aufgaben und Messgrößen ermöglichen eine faire Entscheidung. Der Ort der Engstelle kann je Variante unterschiedlich sein.","hint":"Was muss in beiden Tests gleich sein?","steps":"Vergleiche dieselbe Tätigkeit und dieselbe Art von Maß.","example":"Man kann dieselbe Messgröße an verschiedenen Stellen verwenden.","id":74,"coreId":22,"reserveNo":1,"type":"multi","l":2,"c":3,"caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M5"]},{"title":"Widerspruch zwischen zwei guten Proben erklären","scene":"Übungsvariante: Aufbau A funktioniert für L10. Aufbau B funktioniert für P50. Die Leitung möchte wissen, welcher beim gleichzeitigen Warenzugriff und Vorbeischieben besser funktioniert.","ask":"Welche Prüfung beantwortet die offene Frage?","options":["Beide Beratungsfälle in beiden Aufbauten durchführen.","Nur in A das Licht und nur in B die Pumpe zeigen.","In beiden Varianten prüfen, ob während der Vorführung eine Packung gegriffen werden kann.","Bei B auf den Werkstattweg verzichten, weil dort noch kein Rad stand.","Bei beiden Varianten die Stelle festhalten, an der eine zweite Person mit Rad vorbeigeht.","Den Aufbau mit der kürzeren Spielzeit automatisch empfehlen."],"answer":[0,2,4],"why":"Gleiche Fälle und Beobachtungspunkte machen Unterschiede der Anordnung sichtbar.","hint":"Prüfe, welche Bedingungen bisher nicht gleich waren.","steps":"Wähle gemeinsame Schritte und dokumentiere mögliche Engstellen.","example":"Eine andere Aufgabe kann eine andere Engstelle hervorrufen.","id":75,"coreId":22,"reserveNo":2,"type":"multi","l":2,"c":3,"caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M5"]},{"title":"Ein Ergebnis mit einem Maß belegen","scene":"Im Pitch sagst du: „Bei unserer Empfehlung bleibt der Greifweg frei.“","ask":"Welche Ergänzungen machen die Aussage überzeugender?","options":["Die Stelle im Plan zeigen, die geprüft wurde.","Alle Artikelpreise aufzählen.","Das dort gemessene Maß nennen.","Den Namen der Person nennen, die den Vortrag hält.","Die Beschriftung absichtlich beim Zeigen verdecken.","Nur sagen, dass die Farben gut aussehen."],"answer":[0,2],"why":"Das Beispiel wird prüfbar, wenn Ort und Messwert zugeordnet sind.","hint":"Welche konkrete Information stützt die Aussage?","steps":"Zeige die Stelle und nenne den Beobachtungs- oder Messwert.","example":"Eine Zahl belegt mehr, wenn klar ist, wo sie gemessen wurde.","id":76,"coreId":23,"reserveNo":1,"type":"multi","l":2,"c":4,"caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M5"]},{"title":"Den Arbeitsweg im Pitch nachvollziehbar machen","scene":"Übungsvariante: Im Modell hat euer Team bemerkt, dass der Griff zur Pumpe den Zugang zum Tresen blockierte. Nach einer Änderung klappt beides.","ask":"Was sollte im knappen Pitch vorkommen?","options":["Die gewählte Regalstellung im Plan zeigen.","Die Veränderung nur als „jetzt besser“ beschreiben.","Die beobachtete Blockade als Grund für die Änderung nennen.","Ein Zwischenergebnis aus dem Modell zeigen und erklären, warum es geholfen hat.","Den alten Engpass als Ware im Sortiment zählen.","Die Probe nur nennen, ohne sie mit der Entscheidung zu verbinden."],"answer":[0,2,3],"why":"Plan, Beobachtung und Modellschritt machen deutlich, was geändert wurde und wieso der Aufbau empfohlen wird.","hint":"Sammle Ergebnis, Beleg und Arbeitsweg.","steps":"Wähle je eine konkrete Stelle, Beobachtung und Arbeitsentscheidung.","example":"Eine kurze Aussage zur alten Blockade erklärt, warum das Modell hilfreich war.","id":77,"coreId":23,"reserveNo":2,"type":"multi","l":2,"c":4,"caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M5"]}];
